# ============================================================================
# CACHE UTILITIES CLASS
# ============================================================================
class CacheUtils:
    """
    Centralized cache management utilities.
    Handles CSV caching, freshness checks, regeneration, etc.
    """

    @staticmethod
    def check_and_generate_csv(
        file_name: str,
        generate_function: Callable,  # type: ignore[type-arg]
        freshness_minutes: int | None = None,
    ) -> bool:
        """
        Checks if a CSV file exists and is fresh (modified within the last `freshness_minutes`).
        If not, it runs the `generate_function` to regenerate the file.
        freshness_minutes is now settable via the .env file as CSV_FRESHNESS_MINUTES.

        Args:
            file_name: Name of the CSV file to check/generate
            generate_function: Function to call to generate the file
            freshness_minutes: Optional override for cache freshness threshold

        Returns:
            bool: True if file exists and is fresh or was generated successfully
        """
        logging.debug(
            f"ENTRY: CacheUtils.check_and_generate_csv(file_name={file_name}, generate_function={generate_function.__name__}, freshness_minutes={freshness_minutes})"  # noqa: E501
        )

        if freshness_minutes is None:
            freshness_minutes = CSV_FRESHNESS_MINUTES

        # Get the full path to the CSV file in the data directory
        full_file_path = FilePathUtils.get_csv_path(file_name)

        # Check if the file already exists
        if os.path.exists(full_file_path):
            try:
                # Get the last modified time of the file
                file_mtime = datetime.fromtimestamp(os.path.getmtime(full_file_path))
                logging.debug(f"File I/O: Successfully read modification time for {full_file_path}: {file_mtime}")

                # Check if the file is still fresh
                if datetime.now() - file_mtime < timedelta(minutes=freshness_minutes):
                    # Log that the cached file is being used
                    logging.info(f"! Using cached {file_name} (fresh)")
                    logging.debug("EXIT: check_and_generate_csv - using cached file")
                    return True
                else:
                    # Log that the file is stale and will be regenerated
                    logging.info(f"* {file_name} is older than {freshness_minutes} minutes. Regenerating...")
            except OSError as error:
                logging.error(f"File I/O: Failed to read modification time for {full_file_path}: {error}")
                logging.info(f"* {file_name} exists but cannot read metadata. Regenerating...")
        else:
            # Log that the file does not exist and will be generated
            logging.info(f"* {file_name} not found. Generating...")

        # Call the function to generate the file
        logging.info(f"* Running {generate_function.__name__} to generate {file_name}...")
        try:
            generate_function()
            logging.info(f"! {file_name} generated or refreshed.")
            logging.debug("EXIT: check_and_generate_csv - file generated successfully")
            return True
        except Exception as error:
            logging.error(f"Failed to generate {file_name} using {generate_function.__name__}: {error}")
            logging.debug("EXIT: check_and_generate_csv - generation failed")
            return False

    @staticmethod
    def load_csv_grouped_by_key(filename: str, key: str) -> dict[str, list[dict[str, Any]]]:
        """
        Loads CSV data into a dictionary keyed by the specified column.
        Each key maps to a list of rows (as dictionaries) that share the same key value.

        Args:
            filename: Name of the CSV file to load
            key: Column name to use as the grouping key

        Returns:
            dict: Dictionary where keys are unique values from the key column,
                  and values are lists of row dictionaries
        """
        logging.info(f"Loading CSV file '{filename}' into dictionary keyed by '{key}'...")
        csv_file_path = FilePathUtils.get_csv_path(filename)
        with open(csv_file_path, encoding="utf-8") as file:
            reader = csv.DictReader(file)
            data_dict: dict[str, list[dict[str, Any]]] = {}
            row_count = 0
            for row in reader:
                data_key = row.get(key)
                if data_key is None:
                    logging.warning(f"Row missing key '{key}': {row}")
                    continue
                if data_key not in data_dict:
                    data_dict[data_key] = []
                data_dict[data_key].append(row)
                row_count += 1
            logging.info(f"Loaded {row_count} rows from '{filename}'. Found {len(data_dict)} unique keys for '{key}'.")
        return data_dict

    @staticmethod
    def write_support_data_to_csv(data: dict[str, list[dict[str, Any]]], filename: str) -> None:
        """
        Writes the support package data (a dict of lists of dicts) to a CSV file.
        Each section in 'data' is a list of dictionaries. All unique keys across all sections are used as CSV columns.

        Args:
            data: Dictionary where keys are section names and values are lists of row dictionaries
            filename: Name of the output CSV file
        """
        logging.debug(f"Preparing to write support package to {filename}...")

        fieldnames: set = set()  # type: ignore[type-arg]
        # Collect all unique field names from all sections
        for section_name, section in data.items():
            logging.debug(f"Processing section '{section_name}' with {len(section)} rows.")
            for row in section:
                fieldnames.update(row.keys())
        fieldnames_sorted = sorted(fieldnames)

        logging.debug(f"Final CSV fieldnames: {fieldnames_sorted}")

        # SECURITY: Use proper file path handling to ensure files go to data/ directory
        csv_file_path = FilePathUtils.get_csv_path(filename)
        with open(csv_file_path, mode="w", newline="", encoding="utf-8") as file:
            writer = csv.DictWriter(file, fieldnames=fieldnames_sorted)
            writer.writeheader()
            row_count = 0
            for _section_name, section in data.items():
                for row in section:
                    writer.writerow(row)
                    row_count += 1
            logging.info(f"Wrote {row_count} rows to {csv_file_path} for support package.")

        logging.info(f"Support package written to {csv_file_path}")

    # Known generated cache CSV filenames -- cleared by Menu 175
    GENERATED_FILES: set[str] = {  # Explicit list of MistHelper-generated cache CSVs to protect non-data files
        "AllDevicesWithSiteInfo.csv",
        "GatewayDeviceStats.csv",
        "GatewayDeviceStatsWithSiteInfo.csv",
        "GatewayMgmtIPs.csv",
        "OrgDeviceEvents.csv",
        "OrgInventory.csv",
        "OrgSwitchVCStats.csv",
        "PortStats.csv",
        "SiteList.csv",
        "SitePortStats.csv",
        "VPNPeerStats.csv",
    }

    # Generated CSV filename prefixes -- any file in data/ matching these is a cache candidate
    GENERATED_PREFIXES: tuple[str, ...] = (  # Prefixes that identify auto-generated cache files
        "AllDevices",
        "AuditLogs",
        "DeviceEvents",
        "DevicePort",
        "Gateway",
        "Org",
        "Port",
        "Site",
        "Switch",
        "VPN",
    )

    @staticmethod
    def _is_generated_file(filename: str) -> bool:  # Check if file is MistHelper-generated
        """Return True if the filename matches a known generated cache file."""
        name = os.path.basename(filename)  # Strip any path component for clean matching
        if name in CacheUtils.GENERATED_FILES:  # Exact match against the explicit allowlist
            return True  # Explicitly listed -- safe to delete
        if name.endswith(".csv") and name.startswith(CacheUtils.GENERATED_PREFIXES):  # Prefix match
            return True  # Prefix match -- safe to delete
        return False  # Not a recognised generated file -- leave it alone

    @staticmethod
    def clear_cache() -> None:  # Menu 175: delete all generated cache CSVs from data/ directory
        """Delete all MistHelper-generated cache CSV files from the data/ directory."""
        data_dir = "data"  # Use relative path to data/ directory consistent with FilePathUtils.get_csv_path()
        logging.info("Scanning data directory for generated cache CSVs: %s", data_dir)  # Log scan target
        try:
            candidates = [  # List only safe-to-delete files
                f for f in os.listdir(data_dir) if CacheUtils._is_generated_file(f)
            ]
        except OSError as scan_error:  # Handle permission or missing directory errors gracefully
            logging.error("Failed to list data directory %s: %s", data_dir, scan_error)  # Log I/O failure with context
            print(f"! Error scanning data directory: {scan_error}")  # Surface error to operator
            return  # Abort -- nothing to delete if we can't list the directory
        if not candidates:  # Nothing to delete -- inform operator and return early
            print("! No generated cache CSV files found to delete.")  # User-friendly empty state message
            logging.info("No generated cache CSVs found in %s", data_dir)  # Log empty result
            return  # Early return -- nothing to do
        print(f"Found {len(candidates)} generated cache CSV file(s) to delete:")  # Show operator what will be removed
        for name in sorted(candidates):  # Sort for readable output
            print(f"  {name}")  # List each file so operator knows exactly what is affected
        deleted = 0  # Track successful deletions for summary
        errors = 0  # Track failures for summary
        for name in candidates:  # Delete each identified cache file
            full_path = os.path.join(data_dir, name)  # Build absolute path for deletion
            logging.info("Deleting cache CSV: %s", full_path)  # Log before deletion for audit trail
            try:
                os.remove(full_path)  # Delete the file from disk
                logging.debug("Deleted: %s", full_path)  # Confirm deletion at debug level
                deleted += 1  # Increment success counter
            except OSError as delete_error:  # Handle individual file deletion failures without aborting the batch
                logging.error("Failed to delete %s: %s", full_path, delete_error)  # Log failure with path and reason
                print(f"  ! Could not delete {name}: {delete_error}")  # Surface individual failure to operator
                errors += 1  # Increment error counter
        print(f"! Cache cleared: {deleted} file(s) deleted, {errors} error(s).")  # Summary line for operator
        logging.info("Cache clear complete: %d deleted, %d errors", deleted, errors)  # Log summary for post-run review

    @staticmethod
    def create_address_parse_failures_csv(
        parse_failures: list[dict[str, Any]], filename: str = "AddressParseFailures.csv"
    ) -> None:
        """
        Create a CSV file documenting address parsing failures.

        Args:
            parse_failures: List of parse failure records
            filename: Output filename
        """
        if not parse_failures:
            logging.info("No address parsing failures to document.")
            return

        try:
            output_path = FilePathUtils.get_csv_path(filename)

            with open(output_path, "w", newline="", encoding="utf-8") as f:
                fieldnames = [
                    "site_id",
                    "site_name",
                    "device_id",
                    "device_serial",
                    "device_name",
                    "original_address",
                    "parsed_tokens",
                    "failure_reason",
                    "timestamp",
                ]

                writer = csv.DictWriter(f, fieldnames=fieldnames)
                writer.writeheader()

                for failure in parse_failures:
                    writer.writerow(failure)

            logging.info(f"Address parsing failures documented in: {filename} ({len(parse_failures)} records)")
            print(f"! Address parsing failures documented in: {filename} ({len(parse_failures)} records)")

        except Exception as e:
            logging.error(f"Failed to create address parse failures CSV: {e}")
            print(f"! Failed to create address parse failures CSV: {e}")

    @staticmethod
    def fast_cache_hit(filename: str, max_age_minutes: int = 60) -> bool:  # Check if cached output file is fresh
        """Return True if the file exists in data/ and was written within max_age_minutes.

        Used as a lightweight guard to skip expensive re-generation when a fresh
        output already exists (e.g. a Markdown report generated earlier in the session).

        Args:
            filename: Filename to check inside the data/ directory
            max_age_minutes: How old the file can be before it is considered stale

        Returns:
            bool: True if file exists and is fresh (skip re-generation), False otherwise
        """
        full_path = FilePathUtils.get_csv_path(filename)  # Resolve path inside data/ directory
        logging.debug("fast_cache_hit check for %s (max_age=%d min)", filename, max_age_minutes)  # Log check
        if not os.path.exists(full_path):  # File not present -- always a miss
            logging.debug("fast_cache_hit MISS: %s not found", filename)  # Log miss reason
            return False  # Cache miss -- caller should generate the file
        try:
            age_seconds = time.time() - os.path.getmtime(full_path)  # Seconds since last modification
            age_minutes = age_seconds / 60.0  # Convert to minutes for readable comparison
            if age_minutes <= max_age_minutes:  # File is within the freshness window
                logging.info("fast_cache_hit HIT: %s (%.1f min old)", filename, age_minutes)  # Log cache hit
                print(  # Inform user that cached output is being reused
                    f"! Using cached {filename} ({age_minutes:.0f} min old) -- skipping re-generation."
                )
                return True  # Cache hit -- caller can skip expensive work
            logging.debug("fast_cache_hit MISS: %s is stale (%.1f min old)", filename, age_minutes)  # Log stale
            return False  # File is too old -- cache miss
        except OSError as stat_error:  # Handle race conditions or permission issues
            logging.warning("fast_cache_hit: could not stat %s: %s", filename, stat_error)  # Log I/O issue
            return False  # Treat stat failure as a miss to be safe


