# ORGANIZATION ALARM & EVENT EXPORTER CLASS
# ============================================================================
class OrgAlarmEventExporter:
    """
    Focused exporter for alarm and event time-series data from the Mist API.

    Contains exactly 5 public methods grouped by the 'event/alert' domain:
      - alarms()            : Organization alarms (24h, unacknowledged)
      - alarm_templates()   : Alarm rule templates
      - events()            : Organization events (24h)
      - device_events()     : Device events (24h)
      - device_events_52w() : Device events (52 weeks)

    Extraction Pattern (for decomposing OrgExportUtils further):
      1. Identify up to 5 semantically related methods in OrgExportUtils
      2. Create a new class immediately before OrgExportUtils
      3. Duplicate _export_data() as a private helper if any methods use it
      4. Move methods verbatim (preserve all logic, parameters, API calls)
      5. Update menu_actions dict entries and cross-references
      6. Remove the methods from OrgExportUtils
    """

    @staticmethod
    def _export_data(api_call, data_type, sort_key="name", **api_kwargs):  # type: ignore[no-untyped-def]
        """
        Generic helper to export organization data via APIDataFetcher.

        Args:
            api_call: The mistapi function to call
            data_type: Description of the data type
            sort_key: Field to sort results by
            **api_kwargs: Additional arguments for the API call
        """
        logging.info(f"Starting export of organization {data_type}...")
        safe_data_type = data_type.replace(" ", "").replace("-", "").title()
        filename = f"Org{safe_data_type}.csv"
        APIDataFetcher(
            title=f"Organization {data_type.title()}:",
            api_call=api_call,
            filename=filename,
            sort_key=sort_key,
            limit=1000,
            **api_kwargs,
        ).execute()

    @staticmethod
    def alarms():  # type: ignore[no-untyped-def]
        """
        Export open organization alarms from the past 24 hours to OrgAlarms.csv.
        """
        logging.info("Menu #20: Starting organization alarms export")
        logging.debug("ENTRY: OrgAlarmEventExporter.alarms()")
        hours = TimeUtils.get_dynamic_lookback_hours(24, 1)
        TimeUtils.log_dynamic_lookback("open org alarms export", hours)
        try:
            APIDataFetcher(
                title="Search all Org Alarms:",
                api_call=mistapi.api.v1.orgs.alarms.searchOrgAlarms,
                filename="OrgAlarms.csv",
                limit=1000,
                duration=f"{hours}h",
                acked=False,
            ).execute()
            logging.info("Completed org alarms export and wrote results to OrgAlarms.csv.")
            logging.debug("EXIT: OrgAlarmEventExporter.alarms - success")
        except Exception as error:
            logging.error(f"Failed to export open org alarms: {error}")
            logging.debug("EXIT: OrgAlarmEventExporter.alarms - error")
            raise

    @staticmethod
    def alarm_templates():  # type: ignore[no-untyped-def]
        """Export alarm templates to OrgAlarmTemplates.csv."""
        OrgAlarmEventExporter._export_data(  # type: ignore[no-untyped-call]
            api_call=mistapi.api.v1.orgs.alarmtemplates.listOrgAlarmTemplates,
            data_type="alarm templates",
            sort_key="name",
        )

    @staticmethod
    def events():  # type: ignore[no-untyped-def]
        """Export organization events to OrgEvents.csv."""
        hours = TimeUtils.get_dynamic_lookback_hours(24, 1)
        TimeUtils.log_dynamic_lookback("org events export", hours)
        OrgAlarmEventExporter._export_data(  # type: ignore[no-untyped-call]
            api_call=mistapi.api.v1.orgs.events.searchOrgEvents,
            data_type="events",
            sort_key="timestamp",
            duration=f"{hours}h",
        )

    @staticmethod
    def device_events():  # type: ignore[no-untyped-def]
        """
        Export all device events from the past 24 hours to OrgDeviceEvents.csv.
        """
        logging.info("Menu #21: Starting device events export")
        logging.info("Search Org Device Events:")
        org_id = ConfigUtils.get_cached_or_prompted_org_id()
        hours = TimeUtils.get_dynamic_lookback_hours(24, 1)
        TimeUtils.log_dynamic_lookback("recent device events export", hours)
        duration_param = f"{hours}h"
        response = mistapi.api.v1.orgs.devices.searchOrgDeviceEvents(
            apisession, org_id, device_type="all", limit=1000, duration=duration_param
        )
        rawdata = mistapi.get_all(response=response, mist_session=apisession)
        events = rawdata
        logging.info(f"Fetched {len(events)} device events from the past {hours} hours (duration={duration_param}).")
        DataExporter.save_data_to_output(events, "OrgDeviceEvents.csv")  # type: ignore[no-untyped-call]
        logging.info(f"Device events written to OrgDeviceEvents.csv ({len(events)} rows).")
        print(f"! {len(events)} device events exported to OrgDeviceEvents.csv")
        logging.info(f"Menu #21: Device events export completed - {len(events)} events")
        if events:
            logging.debug("Sample device events: %s", json.dumps(events[:3], indent=2))

    @staticmethod
    def device_events_52w() -> None:
        """
        Export all org device events from the last 52 weeks to OrgDeviceEvents_52w.csv.

        This implementation streams results using the search_after token and writes
        to CSV in a memory-efficient manner with simple checkpointing so it can be
        resumed if interrupted.
        """
        logging.info("Exporting all org device events from the last 52 weeks...")
        org_id = ConfigUtils.get_cached_or_prompted_org_id()
        if not org_id:
            logging.error("No org_id available. Exiting.")
            return

        data_dir = "data"
        os.makedirs(data_dir, exist_ok=True)
        checkpoint_file = os.path.join(data_dir, f"OrgDeviceEvents_52w.{org_id}.checkpoint")
        csv_file = os.path.join(data_dir, "OrgDeviceEvents_52w.csv")

        limit = 1000
        duration = "52w"
        preload_pages = 3  # number of pages to fetch to build a robust header before streaming

        # Try to read an existing checkpoint token to resume
        search_after = None
        if os.path.exists(checkpoint_file):
            try:
                with open(checkpoint_file, encoding="utf-8") as fh:
                    token = fh.read().strip()
                    if token:
                        search_after = token
                        logging.info(f"Resuming OrgDeviceEvents_52w from checkpoint token: {search_after}")
            except Exception as e:
                logging.warning(f"Could not read checkpoint file {checkpoint_file}: {e}")

        def _fetch_page(token: str | None) -> object:
            # Always pass search_after as a keyword; mistapi may ignore None values but accept explicit token
            if token:
                return mistapi.api.v1.orgs.devices.searchOrgDeviceEvents(
                    apisession, org_id, device_type="all", limit=limit, duration=duration, search_after=token
                )
            return mistapi.api.v1.orgs.devices.searchOrgDeviceEvents(
                apisession, org_id, device_type="all", limit=limit, duration=duration
            )

        buffered_rows: list[dict[str, Any]] = []
        page_count = 0
        next_token = None

        # Preload a small number of pages to compute a stable CSV header
        while page_count < preload_pages:
            response = _fetch_page(search_after)
            page_data = getattr(response, "data", None)
            if not page_data:
                break

            if isinstance(page_data, dict):
                results = page_data.get("results", []) or page_data.get("data", [])
                next_token = page_data.get("search_after") or page_data.get("next")
            else:
                results = page_data if isinstance(page_data, list) else []
                next_token = None

            if not results:
                break

            processed = DataProcessingUtils.flatten_nested_fields(results)
            processed = DataProcessingUtils.escape_multiline(processed)  # type: ignore[no-untyped-call]
            buffered_rows.extend(processed)

            if not next_token:
                break

            search_after = next_token
            page_count += 1

        if not buffered_rows:
            logging.info("No device events found for the 52-week period.")
            DataExporter.save_data_to_output([], "OrgDeviceEvents_52w.csv")  # type: ignore[no-untyped-call]
            return

        # Determine CSV header from preloaded rows and write them out
        header_fields = DataProcessingUtils.get_unique_keys(buffered_rows)  # type: ignore[no-untyped-call]
        logging.info(f"Using CSV header with {len(header_fields)} fields for OrgDeviceEvents_52w.csv")

        # Helper: fetch with retries to handle transient API errors/rate limits
        def _fetch_page_with_retries(token: str | None, retries: int = 3, backoff: float = 1.0) -> object:
            last_exc = None
            for attempt in range(retries):
                try:
                    return _fetch_page(token)
                except Exception as exc:  # pragma: no cover - defensive network handling
                    last_exc = exc
                    logging.warning(f"Attempt {attempt + 1}/{retries} to fetch page failed: {exc}")
                    if attempt < retries - 1:
                        sleep_time = backoff * (2**attempt)
                        logging.debug(f"Waiting {sleep_time}s before retrying")
                        time.sleep(sleep_time)
            # If we reach here, all retries failed
            logging.error("Exceeded maximum retries fetching page")
            if last_exc is not None:
                raise last_exc
            raise RuntimeError("All retries failed with no exception captured")

        # Choose output path: CSV (default) or SQLite (streaming)
        table_name = "OrgDeviceEvents_52w"
        if OUTPUT_FORMAT == "sqlite":
            try:
                # Initial write of preloaded rows into SQLite table
                DataExporter.write_with_format_selection(
                    buffered_rows, table_name, format_override="sqlite", api_function_name="searchOrgDeviceEvents"
                )
            except Exception as write_err:
                logging.error(f"Failed to write initial OrgDeviceEvents_52w batch to SQLite: {write_err}")
                raise
        else:
            try:
                with open(csv_file, "w", newline="", encoding="utf-8") as fh:
                    writer = csv.DictWriter(fh, fieldnames=header_fields)
                    writer.writeheader()
                    for row in buffered_rows:
                        writer.writerow({k: row.get(k, "") for k in header_fields})
            except Exception as write_err:
                logging.error(f"Failed to write initial OrgDeviceEvents_52w CSV file: {write_err}")
                raise

        # Persist checkpoint if there are more pages to fetch
        if next_token:
            try:
                with open(checkpoint_file, "w", encoding="utf-8") as fh:
                    fh.write(str(next_token))
            except Exception as e:
                logging.warning(f"Could not write checkpoint file {checkpoint_file}: {e}")

        # Continue streaming remaining pages (if any)
        while next_token:
            # Use retry wrapper for robustness
            response = _fetch_page_with_retries(next_token)
            page_data = getattr(response, "data", None)
            if not page_data:
                break

            if isinstance(page_data, dict):
                results = page_data.get("results", []) or page_data.get("data", [])
                next_token = page_data.get("search_after") or page_data.get("next")
            else:
                results = page_data if isinstance(page_data, list) else []
                next_token = None

            if not results:
                break

            processed = DataProcessingUtils.flatten_nested_fields(results)
            processed = DataProcessingUtils.escape_multiline(processed)  # type: ignore[no-untyped-call]

            if OUTPUT_FORMAT == "sqlite":
                try:
                    DataExporter.write_with_format_selection(
                        processed, table_name, format_override="sqlite", api_function_name="searchOrgDeviceEvents"
                    )
                except Exception as append_err:
                    logging.error(f"Failed to append OrgDeviceEvents_52w to SQLite table {table_name}: {append_err}")
                    raise
            else:
                try:
                    with open(csv_file, "a", newline="", encoding="utf-8") as fh:
                        writer = csv.DictWriter(fh, fieldnames=header_fields)
                        for row in processed:
                            writer.writerow({k: row.get(k, "") for k in header_fields})
                except Exception as append_err:
                    logging.error(f"Failed to append OrgDeviceEvents_52w CSV file: {append_err}")
                    raise

            # Update checkpoint for resume
            if next_token:
                try:
                    with open(checkpoint_file, "w", encoding="utf-8") as fh:
                        fh.write(str(next_token))
                except Exception as e:
                    logging.warning(f"Could not write checkpoint file {checkpoint_file}: {e}")

        # Completed; remove checkpoint file (best-effort)
        try:
            if os.path.exists(checkpoint_file):
                os.remove(checkpoint_file)
        except Exception:
            logging.debug("Could not remove checkpoint file after completion")

        if OUTPUT_FORMAT == "sqlite":
            logging.info(f"All org device events (52w) exported to SQLite table {table_name} (DB: {DATABASE_PATH})")
        else:
            logging.info(f"All org device events (52w) exported to {csv_file}.")


