class OrgClientSecurityExporter:
    """
    Organization Client and Security Exporter

    Handles wireless/wired client data and security event exports.
    Extracted from OrgExportUtils.
    """

    @staticmethod
    def wireless_clients():  # type: ignore[no-untyped-def]
        """Export wireless client statistics for the entire organization to OrgWirelessClients.csv."""
        OrgExportUtils.export_data(  # type: ignore[no-untyped-call]
            api_call=mistapi.api.v1.orgs.clients.searchOrgWirelessClients, data_type="wireless clients", sort_key="mac"
        )

    @staticmethod
    def wired_clients():  # type: ignore[no-untyped-def]
        """Export wired client statistics for the entire organization to OrgWiredClients.csv."""
        OrgExportUtils.export_data(  # type: ignore[no-untyped-call]
            api_call=mistapi.api.v1.orgs.wired_clients.searchOrgWiredClients, data_type="wired clients", sort_key="mac"
        )

    @staticmethod
    def security_events(fast: bool = False):  # type: ignore[no-untyped-def]  # noqa: C901, PLR0912, PLR0915
        """Export security policies, intelligence profiles, and rogue data.

        Fast Mode Behavior:
            - Cache hit: If all 3 output CSVs exist and are fresh, skip entirely.
            - Reduced lookback: Uses dynamic lookback (1h in test) instead of hardcoded 7d.
        """
        output_files = ["OrgSecurityPolicies.csv", "OrgSecIntelProfiles.csv", "OrgRogueData.csv"]
        if fast:
            all_fresh = True
            for output_file in output_files:
                try:
                    path = FilePathUtils.get_csv_path(output_file)
                    if os.path.exists(path):
                        age_minutes = (time.time() - os.path.getmtime(path)) / 60.0
                        if age_minutes >= CSV_FRESHNESS_MINUTES:
                            all_fresh = False
                            break
                    else:
                        all_fresh = False
                        break
                except Exception:
                    all_fresh = False
                    break
            if all_fresh:
                logging.info("Fast mode cache hit: All security data CSVs are fresh; skipping fetch.")
                print("* Fast mode: Using cached security data (all files fresh)")
                return
        print("Export Organization Security Data:")
        logging.info("Starting export of organization security policies, intelligence profiles, and rogue data...")
        emitter = PROGRESS_EMITTER
        if emitter:
            emitter.emit_progress_start("42", "security_events", 3)
        op_start = time.time()
        current_org_id = ConfigUtils.get_cached_or_prompted_org_id()
        policies: list[dict[str, Any]] = []
        try:
            logging.info("Fetching organization security policies (secpolicies)...")
            resp = mistapi.api.v1.orgs.secpolicies.listOrgSecPolicies(apisession, current_org_id, limit=1000)
            policies = mistapi.get_all(response=resp, mist_session=apisession) or []
            logging.debug(f"Security policies fetched: {len(policies)}")
        except Exception as e:
            logging.warning(f"Failed to fetch security policies: {e}")
        if policies:
            processed = DataProcessingUtils.flatten_nested_fields(policies)
            processed = DataProcessingUtils.escape_multiline(processed)  # type: ignore[no-untyped-call]
            DataExporter.save_data_to_output(processed, "OrgSecurityPolicies.csv")  # type: ignore[no-untyped-call]
            print(f"! {len(processed)} security policies exported to OrgSecurityPolicies.csv")
            logging.info(f"Exported {len(processed)} security policies to OrgSecurityPolicies.csv")
        else:
            print("! 0 security policies exported to OrgSecurityPolicies.csv (no policies found)")
            logging.warning("No data to export for OrgSecurityPolicies.csv (zero policies returned).")
            DataExporter.save_data_to_output([], "OrgSecurityPolicies.csv")  # type: ignore[no-untyped-call]
        secintel_profiles: list[dict[str, Any]] = []
        try:
            logging.info("Fetching organization security intelligence profiles...")
            resp_secintel = mistapi.api.v1.orgs.secintelprofiles.listOrgSecIntelProfiles(apisession, current_org_id)
            secintel_profiles = mistapi.get_all(response=resp_secintel, mist_session=apisession) or []
            logging.debug(f"Security intelligence profiles fetched: {len(secintel_profiles)}")
        except Exception as e:
            logging.warning(f"Failed to fetch security intelligence profiles: {e}")
        if secintel_profiles:
            processed_si = DataProcessingUtils.flatten_nested_fields(secintel_profiles)
            processed_si = DataProcessingUtils.escape_multiline(processed_si)  # type: ignore[no-untyped-call]
            DataExporter.save_data_to_output(processed_si, "OrgSecIntelProfiles.csv")  # type: ignore[no-untyped-call]
            print(f"! {len(processed_si)} security intelligence profiles exported to OrgSecIntelProfiles.csv")
            logging.info(f"Exported {len(processed_si)} security intelligence profiles to OrgSecIntelProfiles.csv")
        else:
            print("! 0 security intelligence profiles exported to OrgSecIntelProfiles.csv (no profiles found)")
            logging.warning("No data to export for OrgSecIntelProfiles.csv (zero profiles returned).")
            DataExporter.save_data_to_output([], "OrgSecIntelProfiles.csv")  # type: ignore[no-untyped-call]
        lookback_hours = TimeUtils.get_dynamic_lookback_hours(168, 1)
        rogue_duration = f"{lookback_hours}h"
        TimeUtils.log_dynamic_lookback("rogue data fetch", lookback_hours)
        logging.info("Fetching rogue APs and clients from all sites via insights...")
        CacheUtils.check_and_generate_csv("SiteList.csv", OrgSiteExporter.sites)
        all_rogue_aps: list[dict[str, Any]] = []
        all_rogue_clients: list[dict[str, Any]] = []
        try:
            site_list_path = FilePathUtils.get_csv_path("SiteList.csv")
            with open(site_list_path, encoding="utf-8") as f:
                sites = list(csv.DictReader(f))
            for site in tqdm(sites, desc="Sites", unit="site"):  # type: ignore[no-untyped-call]
                if ConfigUtils.check_stop_signal():
                    break
                site_id = site.get("id")
                site_name = site.get("name", "Unknown Site")
                if not site_id:
                    continue
                try:
                    response_aps = mistapi.api.v1.sites.insights.listSiteRogueAPs(
                        apisession, site_id, duration=rogue_duration, limit=1000
                    )
                    site_rogue_aps = mistapi.get_all(response=response_aps, mist_session=apisession) or []
                    for rogue_access_point in site_rogue_aps:
                        rogue_access_point["site_id"] = site_id
                        rogue_access_point["site_name"] = site_name
                        rogue_access_point["rogue_type"] = "AP"
                    all_rogue_aps.extend(site_rogue_aps)
                    response_clients = mistapi.api.v1.sites.insights.listSiteRogueClients(
                        apisession, site_id, duration=rogue_duration, limit=1000
                    )
                    site_rogue_clients = mistapi.get_all(response=response_clients, mist_session=apisession) or []
                    for client in site_rogue_clients:
                        client["site_id"] = site_id
                        client["site_name"] = site_name
                        client["rogue_type"] = "Client"
                    all_rogue_clients.extend(site_rogue_clients)
                    logging.info(
                        f"! Fetched {len(site_rogue_aps)} rogue APs and {len(site_rogue_clients)} rogue clients from site: {site_name}"  # noqa: E501
                    )
                except Exception as e:
                    logging.warning(f"! Failed to fetch rogue data from site {site_name}: {e}")
                    continue
        except Exception as e:
            logging.error(f"Failed to process sites for rogue data: {e}")
        all_rogue_data = all_rogue_aps + all_rogue_clients
        if all_rogue_data:
            processed_r = DataProcessingUtils.flatten_nested_fields(all_rogue_data)
            processed_r = DataProcessingUtils.escape_multiline(processed_r)  # type: ignore[no-untyped-call]
            DataExporter.save_data_to_output(processed_r, "OrgRogueData.csv")  # type: ignore[no-untyped-call]
            print(f"! {len(processed_r)} rogue devices exported to OrgRogueData.csv")
            logging.info(f"Exported {len(processed_r)} rogue devices to OrgRogueData.csv")
        else:
            print("! 0 rogue devices exported to OrgRogueData.csv (no rogue devices found)")
            logging.info("No rogue devices found across all sites (OrgRogueData.csv written empty).")
            DataExporter.save_data_to_output([], "OrgRogueData.csv")  # type: ignore[no-untyped-call]
        print("Security data export completed (3 files generated)")
        logging.info("Completed security policies, intelligence profiles, and rogue data export aggregate.")
        if emitter:
            emitter.emit_progress_complete("42", "security_events", 3, 3, False, time.time() - op_start)

    @staticmethod
    def rogue_clients(fast: bool = False):  # type: ignore[no-untyped-def]  # noqa: C901, PLR0915
        """Export rogue clients to OrgRogueClients.csv.

        Fast Mode Behavior:
            - Cache hit: If fresh CSV exists, skip fetch entirely.
            - Reduced lookback: Dynamic hours (1h in test) instead of hardcoded 7d.
        """
        output_file = "OrgRogueClients.csv"
        if fast:
            try:
                path = FilePathUtils.get_csv_path(output_file)
                if os.path.exists(path):
                    age_minutes = (time.time() - os.path.getmtime(path)) / 60.0
                    if age_minutes < CSV_FRESHNESS_MINUTES:
                        logging.info(
                            f"Fast mode cache hit: {output_file} is fresh ({age_minutes:.1f}m); skipping fetch."
                        )
                        print(f"* Fast mode: Using cached {output_file} (age {age_minutes:.1f}m)")
                        return
            except Exception as cache_error:
                logging.debug(f"Fast mode freshness check failed for {output_file}: {cache_error}")
        logging.info("Starting export of rogue clients from all sites...")
        lookback_hours = TimeUtils.get_dynamic_lookback_hours(168, 1)
        rogue_duration = f"{lookback_hours}h"
        TimeUtils.log_dynamic_lookback("rogue clients fetch", lookback_hours)
        CacheUtils.check_and_generate_csv("SiteList.csv", OrgSiteExporter.sites)
        all_rogue_clients: list[dict[str, Any]] = []
        try:
            site_list_path = FilePathUtils.get_csv_path("SiteList.csv")
            with open(site_list_path, encoding="utf-8") as f:
                sites = list(csv.DictReader(f))
            for site in tqdm(sites, desc="Sites", unit="site"):  # type: ignore[no-untyped-call]
                if ConfigUtils.check_stop_signal():
                    break
                site_id = site.get("id")
                site_name = site.get("name", "Unknown Site")
                if not site_id:
                    continue
                try:
                    response = mistapi.api.v1.sites.insights.listSiteRogueClients(
                        apisession, site_id, duration=rogue_duration, limit=1000
                    )
                    clients = mistapi.get_all(response=response, mist_session=apisession)
                    for client in clients:
                        client["site_id"] = site_id
                        client["site_name"] = site_name
                    all_rogue_clients.extend(clients)
                    logging.info(f"! Fetched {len(clients)} rogue clients from site: {site_name}")
                except Exception as e:
                    logging.warning(f"! Failed to fetch rogue clients from site {site_name}: {e}")
                    continue
        except Exception as e:
            logging.error(f"Failed to process sites for rogue clients: {e}")
            return
        if all_rogue_clients:
            flattened = DataProcessingUtils.flatten_nested_fields(all_rogue_clients)
            sanitized = DataProcessingUtils.escape_multiline(flattened)  # type: ignore[no-untyped-call]
            DataExporter.save_data_to_output(sanitized, "OrgRogueClients")  # type: ignore[no-untyped-call]
            logging.info(f"! {len(all_rogue_clients)} rogue clients exported to OrgRogueClients")
            print(f"! {len(all_rogue_clients)} rogue clients exported to OrgRogueClients")
        else:
            logging.info("No rogue clients found across all sites")
            print(" No rogue clients detected across all sites")

    @staticmethod
    def rogue_aps(fast: bool = False):  # type: ignore[no-untyped-def]  # noqa: C901, PLR0915
        """Export rogue APs to OrgRogueAps.csv.

        Fast Mode Behavior:
            - Cache hit: If fresh CSV exists, skip fetch entirely.
            - Reduced lookback: Dynamic hours (1h in test) instead of hardcoded 7d.
        """
        output_file = "OrgRogueAPs.csv"
        if fast:
            try:
                path = FilePathUtils.get_csv_path(output_file)
                if os.path.exists(path):
                    age_minutes = (time.time() - os.path.getmtime(path)) / 60.0
                    if age_minutes < CSV_FRESHNESS_MINUTES:
                        logging.info(
                            f"Fast mode cache hit: {output_file} is fresh ({age_minutes:.1f}m); skipping fetch."
                        )
                        print(f"* Fast mode: Using cached {output_file} (age {age_minutes:.1f}m)")
                        return
            except Exception as cache_error:
                logging.debug(f"Fast mode freshness check failed for {output_file}: {cache_error}")
        logging.info("Starting export of rogue APs from all sites...")
        lookback_hours = TimeUtils.get_dynamic_lookback_hours(168, 1)
        rogue_duration = f"{lookback_hours}h"
        TimeUtils.log_dynamic_lookback("rogue APs fetch", lookback_hours)
        CacheUtils.check_and_generate_csv("SiteList.csv", OrgSiteExporter.sites)
        all_rogue_aps: list[dict[str, Any]] = []
        try:
            site_list_path = FilePathUtils.get_csv_path("SiteList.csv")
            with open(site_list_path, encoding="utf-8") as f:
                sites = list(csv.DictReader(f))
            for site in tqdm(sites, desc="Sites", unit="site"):  # type: ignore[no-untyped-call]
                if ConfigUtils.check_stop_signal():
                    break
                site_id = site.get("id")
                site_name = site.get("name", "Unknown Site")
                if not site_id:
                    continue
                try:
                    response = mistapi.api.v1.sites.insights.listSiteRogueAPs(
                        apisession, site_id, duration=rogue_duration, limit=1000
                    )
                    aps = mistapi.get_all(response=response, mist_session=apisession)
                    for access_point in aps:
                        access_point["site_id"] = site_id
                        access_point["site_name"] = site_name
                    all_rogue_aps.extend(aps)
                    logging.info(f"! Fetched {len(aps)} rogue APs from site: {site_name}")
                except Exception as e:
                    logging.warning(f"! Failed to fetch rogue APs from site {site_name}: {e}")
                    continue
        except Exception as e:
            logging.error(f"Failed to process sites for rogue APs: {e}")
            return
        if all_rogue_aps:
            flattened = DataProcessingUtils.flatten_nested_fields(all_rogue_aps)
            sanitized = DataProcessingUtils.escape_multiline(flattened)  # type: ignore[no-untyped-call]
            DataExporter.save_data_to_output(sanitized, "OrgRogueAPs")  # type: ignore[no-untyped-call]
            logging.info(f"! {len(all_rogue_aps)} rogue APs exported to OrgRogueAPs")
            print(f"! {len(all_rogue_aps)} rogue APs exported to OrgRogueAPs")
        else:
            logging.info("No rogue APs found across all sites")
            print(" No rogue APs detected across all sites")


class FilterOperatorEngine:
    """Shared operator catalog, normalization, and evaluation for client search filtering."""

    OPERATOR_CATALOG: list[str] = [
        "is",
        "is not",
        "contains",
        "doesn't contain",
        "starts with",
        "doesn't start with",
        "ends with",
        "doesn't end with",
        "is blank",
        "is not blank",
        "is null",
        "is not null",
    ]

    VALUE_REQUIRED_OPERATORS: frozenset[str] = frozenset(
        {
            "is",
            "is not",
            "contains",
            "doesn't contain",
            "starts with",
            "doesn't start with",
            "ends with",
            "doesn't end with",
        }
    )

    REMOTE_PREFILTER_OPERATORS: frozenset[str] = frozenset(
        {
            "is",
        }
    )

    @staticmethod
    def normalize_mac(mac_value: str) -> str:
        """Remove delimiters and lowercase for delimiter-insensitive comparison."""
        if not mac_value:
            return ""
        return re.sub(r"[:\-.]", "", mac_value).lower()

    @staticmethod
    def normalize_text(text_value: str) -> str:
        """Lowercase and strip for case-insensitive comparison."""
        if not text_value:
            return ""
        return text_value.strip().lower()

    @staticmethod
    def evaluate_operator(field_value: str | None, operator: str, search_value: str, is_mac: bool = False) -> bool:
        """Evaluate a single operator against a field value. Returns True if record matches."""
        if operator in ("is null", "is not null", "is blank", "is not blank"):
            return FilterOperatorEngine._evaluate_null_blank(field_value, operator)
        if field_value is None or str(field_value).strip() == "":
            return False
        normalized = FilterOperatorEngine._normalize_pair(str(field_value), search_value, is_mac)
        return FilterOperatorEngine._evaluate_value_operator(normalized[0], operator, normalized[1])

    @staticmethod
    def validate_operator_value(operator: str, value: str, field_name: str) -> bool:
        """Validate that value-required operators have non-empty normalized values."""
        if operator in FilterOperatorEngine.VALUE_REQUIRED_OPERATORS:
            if not value or not value.strip():
                logging.warning(f"Operator '{operator}' for {field_name} requires a non-empty value")
                print(f"\n  Operator '{operator}' requires a value for {field_name}. Please try again.")
                return False
        return True

    @staticmethod
    def _evaluate_null_blank(field_value: str | None, operator: str) -> bool:
        """Evaluate null/blank operators against a field value."""
        if operator == "is null":
            return field_value is None
        if operator == "is not null":
            return field_value is not None
        if operator == "is blank":
            return field_value is not None and str(field_value).strip() == ""
        return field_value is not None and str(field_value).strip() != ""

    @staticmethod
    def _normalize_pair(field_value: str, search_value: str, is_mac: bool) -> tuple[str, str]:
        """Normalize field and search values for comparison."""
        if is_mac:
            return FilterOperatorEngine.normalize_mac(field_value), FilterOperatorEngine.normalize_mac(search_value)
        return FilterOperatorEngine.normalize_text(field_value), FilterOperatorEngine.normalize_text(search_value)

    @staticmethod
    def _evaluate_value_operator(field: str, operator: str, search: str) -> bool:
        """Evaluate value-based positional/equality operators."""
        operator_map: dict[str, Any] = {
            "is": lambda f, s: f == s,
            "is not": lambda f, s: f != s,
            "contains": lambda f, s: s in f,
            "doesn't contain": lambda f, s: s not in f,
            "starts with": lambda f, s: f.startswith(s),
            "doesn't start with": lambda f, s: not f.startswith(s),
            "ends with": lambda f, s: f.endswith(s),
            "doesn't end with": lambda f, s: not f.endswith(s),
        }
        evaluator = operator_map.get(operator)
        return evaluator(field, search) if evaluator else False


class GlobalWiredClientReportGenerator:
    """Generates organization-wide wired client reports with operator-based MAC/manufacturer filtering."""

    @staticmethod
    def execute() -> None:
        """Main entry point from menu system."""
        org_id = ConfigUtils.get_cached_or_prompted_org_id()
        criteria = GlobalWiredClientReportGenerator._prompt_filter_criteria()
        if criteria is False:
            return
        records, remote_used = GlobalWiredClientReportGenerator._fetch_clients(org_id, criteria)
        if not records:
            logging.warning("No wired clients retrieved from API")
            print("\n  No wired clients found in the organization.")
            return
        matched, metadata = GlobalWiredClientReportGenerator._apply_filters(records, criteria, remote_used)
        GlobalWiredClientReportGenerator._write_outputs(matched, metadata)

    @staticmethod
    def _prompt_filter_criteria() -> dict[str, str] | None | bool:
        """Collect optional MAC and manufacturer filter criteria from user."""
        print("\n--- Global Wired Client Report ---")
        print("Optional filters (press Enter to skip):\n")
        criteria: dict[str, str] = {}
        mac_result = GlobalWiredClientReportGenerator._collect_single_filter("MAC address", "mac", criteria)
        if mac_result is False:
            return False
        mfg_result = GlobalWiredClientReportGenerator._collect_single_filter("Manufacturer", "mfg", criteria)
        if mfg_result is False:
            return False
        return criteria if criteria else None

    @staticmethod
    def _collect_single_filter(field_label: str, key_prefix: str, criteria: dict[str, str]) -> bool | None:
        """Collect a single field operator and value. Returns False on validation failure."""
        operator = GlobalWiredClientReportGenerator._prompt_operator(field_label)
        if not operator:
            return None
        criteria[f"{key_prefix}_operator"] = operator
        if operator not in FilterOperatorEngine.VALUE_REQUIRED_OPERATORS:
            return True
        value = InputUtils.safe_input(f"  Enter {field_label} value: ", context=f"wired_report_{key_prefix}_filter")
        if not FilterOperatorEngine.validate_operator_value(operator, value, field_label):
            return False
        criteria[f"{key_prefix}_value"] = value
        return True

    @staticmethod
    def _prompt_operator(field_name: str) -> str | None:
        """Display operator selection menu and return chosen operator or None."""
        print(f"  {field_name} filter operator:")
        print("    0. No filter (skip)")
        for index, operator in enumerate(FilterOperatorEngine.OPERATOR_CATALOG, 1):
            print(f"    {index}. {operator}")
        choice = InputUtils.safe_input(
            f"  Select {field_name} operator (0-12, default 0): ",
            default_value="0",
            context=f"wired_report_{field_name.lower().replace(' ', '_')}_operator",
        )
        if choice == "0" or not choice:
            return None
        try:
            index = int(choice) - 1
            if 0 <= index < len(FilterOperatorEngine.OPERATOR_CATALOG):
                selected = FilterOperatorEngine.OPERATOR_CATALOG[index]
                logging.info(f"Selected {field_name} operator: {selected}")
                return selected
        except ValueError:
            pass
        print(f"  Invalid selection. No {field_name} filter will be applied.")
        return None

    @staticmethod
    def _fetch_clients(org_id: str, criteria: dict[str, str] | None) -> tuple[list[dict[str, Any]], bool]:
        """Fetch org-wide wired clients with optional remote prefiltering."""
        remote_params: dict[str, Any] = {"limit": 1000}
        remote_used = False
        if criteria:
            remote_used = GlobalWiredClientReportGenerator._build_remote_params(criteria, remote_params)
        try:
            logging.info("Fetching organization wired clients...")
            print("\n  Retrieving wired clients from organization...")
            response = mistapi.api.v1.orgs.wired_clients.searchOrgWiredClients(
                apisession,
                org_id,
                **remote_params,
            )
            records = mistapi.get_all(response=response, mist_session=apisession) or []
            logging.info(f"Retrieved {len(records)} wired client records")
            print(f"  Retrieved {len(records)} wired client records")
            return records, remote_used
        except Exception as exception:
            logging.error(f"Failed to fetch wired clients: {exception}", exc_info=True)
            print(f"\n  Error retrieving wired clients: {exception}")
            return [], False

    @staticmethod
    def _build_remote_params(criteria: dict[str, str], params: dict[str, Any]) -> bool:
        """Add best-effort remote prefilter params. Returns True if any were added."""
        remote_used = False
        mac_operator = criteria.get("mac_operator", "")
        if mac_operator in FilterOperatorEngine.REMOTE_PREFILTER_OPERATORS:
            mac_value = criteria.get("mac_value", "")
            if mac_value:
                params["mac"] = mac_value
                remote_used = True
                logging.info(f"Remote prefilter: mac={mac_value}")
        mfg_operator = criteria.get("mfg_operator", "")
        if mfg_operator in FilterOperatorEngine.REMOTE_PREFILTER_OPERATORS:
            mfg_value = criteria.get("mfg_value", "")
            if mfg_value:
                params["manufacture"] = mfg_value
                remote_used = True
                logging.info(f"Remote prefilter: manufacture={mfg_value}")
        return remote_used

    @staticmethod
    def _apply_filters(
        records: list[dict[str, Any]],
        criteria: dict[str, str] | None,
        remote_used: bool,
    ) -> tuple[list[dict[str, Any]], dict[str, Any]]:
        """Apply local authoritative filtering with AND logic. Returns matched records and metadata."""
        total_retrieved = len(records)
        has_filters = criteria is not None and bool(criteria)
        if not has_filters:
            metadata = GlobalWiredClientReportGenerator._build_metadata(
                total_retrieved,
                total_retrieved,
                remote_used,
                False,
                criteria,
            )
            return records, metadata
        matched = [record for record in records if GlobalWiredClientReportGenerator._record_matches(record, criteria)]
        metadata = GlobalWiredClientReportGenerator._build_metadata(
            total_retrieved,
            len(matched),
            remote_used,
            True,
            criteria,
        )
        return matched, metadata

    @staticmethod
    def _record_matches(record: dict[str, Any], criteria: dict[str, str]) -> bool:
        """Evaluate a single record against all active filter criteria with AND logic."""
        mac_operator = criteria.get("mac_operator")
        if mac_operator:
            mac_value = criteria.get("mac_value", "")
            field_value = record.get("mac")
            if not FilterOperatorEngine.evaluate_operator(field_value, mac_operator, mac_value, is_mac=True):
                return False
        mfg_operator = criteria.get("mfg_operator")
        if mfg_operator:
            mfg_value = criteria.get("mfg_value", "")
            field_value = record.get("manufacture")
            if not FilterOperatorEngine.evaluate_operator(field_value, mfg_operator, mfg_value, is_mac=False):
                return False
        return True

    @staticmethod
    def _build_metadata(
        retrieved: int,
        matched: int,
        remote_used: bool,
        local_used: bool,
        criteria: dict[str, str] | None,
    ) -> dict[str, Any]:
        """Build filtering decision metadata for output summary."""
        metadata: dict[str, Any] = {
            "records_retrieved": retrieved,
            "records_matched": matched,
            "remote_filter_used": remote_used,
            "local_filter_used": local_used,
            "generated_at": datetime.now(UTC).isoformat(),  # UTC ISO timestamp for report metadata
        }
        if criteria:
            if criteria.get("mac_operator"):
                metadata["mac_operator"] = criteria["mac_operator"]
                metadata["mac_value"] = criteria.get("mac_value", "")
            if criteria.get("mfg_operator"):
                metadata["mfg_operator"] = criteria["mfg_operator"]
                metadata["mfg_value"] = criteria.get("mfg_value", "")
        return metadata

    @staticmethod
    def _write_outputs(matched: list[dict[str, Any]], metadata: dict[str, Any]) -> None:
        """Write matched records to both local report artifact and standard export."""
        matched_count = metadata["records_matched"]
        retrieved_count = metadata["records_retrieved"]
        print(f"\n  Matched {matched_count} of {retrieved_count} wired client records")
        if matched_count == 0:
            logging.info("Zero records matched filters -- producing empty outputs")
            print("  No records matched the specified filters.")
        GlobalWiredClientReportGenerator._write_standard_export(matched)
        GlobalWiredClientReportGenerator._write_local_report(matched, metadata)

    @staticmethod
    def _write_standard_export(matched: list[dict[str, Any]]) -> None:
        """Write matched records through the standard CSV/SQLite export path."""
        if matched:
            flattened = DataProcessingUtils.flatten_nested_fields(matched)
            sanitized = DataProcessingUtils.escape_multiline(flattened)  # type: ignore[no-untyped-call]
        else:
            sanitized = []
        DataExporter.write_with_format_selection(
            sanitized,
            "GlobalWiredClientReport",
            api_function_name="globalWiredClientReport",
        )
        logging.info(f"Standard export: {len(sanitized)} records to GlobalWiredClientReport")

    @staticmethod
    def _write_local_report(matched: list[dict[str, Any]], metadata: dict[str, Any]) -> None:
        """Write local report artifact with summary metadata to data/ directory."""
        report_path = os.path.join("data", "GlobalWiredClientReport_summary.json")
        report_payload: dict[str, Any] = {
            "summary": metadata,
            "record_count": len(matched),
        }
        try:
            with open(report_path, "w", encoding="utf-8") as report_file:
                json.dump(report_payload, report_file, indent=2, default=str)
            logging.info(f"Local report artifact written to {report_path}")
            print(f"  Report summary written to {report_path}")
        except OSError as error:
            logging.error(f"Failed to write local report artifact: {error}")
            print(f"  Warning: Could not write report summary to {report_path}")


class WiredClientManufacturerReportGenerator:
    """Generates wired client reports filtered by interactive manufacturer selection."""

    @staticmethod
    def execute() -> None:
        """Main entry point: always export ALL, then optionally filter by manufacturer."""
        org_id = ConfigUtils.get_cached_or_prompted_org_id()
        records = WiredClientManufacturerReportGenerator._fetch_all_clients(org_id)
        if not records:
            logging.warning("No wired clients retrieved from API")
            print("\n  No wired clients found in the organization.")
            return
        WiredClientManufacturerReportGenerator._write_outputs(records, "")
        summary = WiredClientManufacturerReportGenerator._build_manufacturer_summary(records)
        selected = WiredClientManufacturerReportGenerator._prompt_selection(summary)
        if not selected:
            return
        filtered = WiredClientManufacturerReportGenerator._filter_by_manufacturer(records, selected)
        WiredClientManufacturerReportGenerator._write_outputs(filtered, selected)

    @staticmethod
    def _fetch_all_clients(org_id: str) -> list[dict[str, Any]]:
        """Fetch all wired clients across the organization without filters."""
        try:
            logging.info("Fetching all organization wired clients for manufacturer report...")
            print("\n  Retrieving all wired clients from organization...")
            response = mistapi.api.v1.orgs.wired_clients.searchOrgWiredClients(
                apisession,
                org_id,
                limit=1000,
            )
            records = mistapi.get_all(response=response, mist_session=apisession) or []
            logging.info(f"Retrieved {len(records)} wired client records")
            print(f"  Retrieved {len(records)} wired client records")
            return records
        except Exception as exception:
            logging.error(f"Failed to fetch wired clients: {exception}", exc_info=True)
            print(f"\n  Error retrieving wired clients: {exception}")
            return []

    @staticmethod
    def _build_manufacturer_summary(records: list[dict[str, Any]]) -> list[tuple[str, int]]:
        """Extract unique manufacturers with client counts, sorted alphabetically."""
        manufacturer_counts: dict[str, int] = {}
        for record in records:
            manufacturer = str(record.get("manufacture", "Unknown") or "Unknown").strip()
            manufacturer_counts[manufacturer] = manufacturer_counts.get(manufacturer, 0) + 1
        sorted_manufacturers = sorted(manufacturer_counts.items(), key=lambda item: item[0].lower())
        return sorted_manufacturers

    @staticmethod
    def _prompt_selection(summary: list[tuple[str, int]]) -> str | None:
        """Display manufacturer list with counts and prompt user to select one."""
        total_clients = sum(count for _, count in summary)
        print(f"\n  Found {total_clients} clients from {len(summary)} manufacturers\n")
        print(f"  {'#':<5} {'Manufacturer':<45} {'Count':>8}")
        print(f"  {'-' * 5} {'-' * 45} {'-' * 8}")
        for index, (manufacturer, count) in enumerate(summary, 1):
            display_name = manufacturer[:44]
            print(f"  {index:<5} {display_name:<45} {count:>8}")
        choice = InputUtils.safe_input(
            "\n  Enter manufacturer number for filtered report (Enter to skip): ",
            default_value="",
            allow_empty=True,
            context="manufacturer_report_selection",
        )
        if not choice:
            return None
        try:
            selection_index = int(choice)
        except ValueError:
            print("  Invalid selection.")
            return None
        if 1 <= selection_index <= len(summary):
            selected_manufacturer = summary[selection_index - 1][0]
            logging.info(f"User selected manufacturer: {selected_manufacturer}")
            return selected_manufacturer
        print("  Selection out of range.")
        return None

    @staticmethod
    def _filter_by_manufacturer(records: list[dict[str, Any]], manufacturer: str) -> list[dict[str, Any]]:
        """Filter records by selected manufacturer. Empty string means no filter (all records)."""
        if not manufacturer:
            return records
        normalized_selection = manufacturer.strip().lower()
        return [
            record
            for record in records
            if str(record.get("manufacture", "") or "").strip().lower() == normalized_selection
        ]

    @staticmethod
    def _build_filename(manufacturer: str) -> str:
        """Build a unique filename incorporating the selected manufacturer."""
        if not manufacturer:
            slug = "ALL"
        else:
            slug = re.sub(r"[^\w]+", "_", manufacturer).strip("_")[:40]
        return f"WiredClientManufacturerReport_{slug}"

    @staticmethod
    def _write_outputs(filtered: list[dict[str, Any]], manufacturer: str) -> None:
        """Write filtered records through the standard CSV/SQLite export path."""
        label = manufacturer if manufacturer else "ALL manufacturers"
        filename = WiredClientManufacturerReportGenerator._build_filename(manufacturer)
        print(f"\n  Exporting {len(filtered)} records for: {label}")
        if filtered:
            flattened = DataProcessingUtils.flatten_nested_fields(filtered)
            sanitized = DataProcessingUtils.escape_multiline(flattened)  # type: ignore[no-untyped-call]
        else:
            sanitized = []
        DataExporter.write_with_format_selection(
            sanitized,
            filename,
            api_function_name="wiredClientManufacturerReport",
        )
        print(f"  Exported to: data/{filename}.csv")
        logging.info(f"Manufacturer report exported: {len(sanitized)} records for {label} -> {filename}")


class OrgAdminExporter:
    """
    Organization Admin and License Exporter

    Handles API tokens, admins, SSO, license, and usage exports.
    Extracted from OrgExportUtils.
    """

    @staticmethod
    def api_tokens():  # type: ignore[no-untyped-def]
        """Export organization API tokens to OrgApiTokens.csv."""
        logging.info("Starting export of organization api tokens...")
        APIDataFetcher(
            title="Organization Api Tokens:",
            api_call=mistapi.api.v1.orgs.apitokens.listOrgApiTokens,
            filename="OrgApiTokens.csv",
            sort_key="name",
        ).execute()

    @staticmethod
    def admins():  # type: ignore[no-untyped-def]
        """Export organization admins to OrgAdmins.csv."""
        logging.info("Starting export of organization admins...")
        APIDataFetcher(
            title="Organization Admins:",
            api_call=mistapi.api.v1.orgs.admins.listOrgAdmins,
            filename="OrgAdmins.csv",
            sort_key="name",
        ).execute()

    @staticmethod
    def sso():  # type: ignore[no-untyped-def]
        """Export organization SSO configuration to OrgSso.csv."""
        OrgExportUtils.export_data(api_call=mistapi.api.v1.orgs.ssos.listOrgSsos, data_type="sso", sort_key="name")  # type: ignore[no-untyped-call]

    @staticmethod
    def licenses():  # type: ignore[no-untyped-def]
        """Export organization licenses to OrgLicenses.csv."""
        logging.info("Starting export of organization licenses (canonical endpoint)...")
        filename = "OrgLicenses.csv"
        current_org_id = ConfigUtils.get_cached_or_prompted_org_id()
        try:
            list_func = getattr(mistapi.api.v1.orgs.licenses, "listOrgLicenses", None)
            if list_func is None:
                logging.debug("listOrgLicenses wrapper not present in mistapi library; performing direct GET /licenses")
                raw_url = f"/api/v1/orgs/{current_org_id}/licenses"
                if apisession is None:
                    raise ValueError("API session not initialized")
                response = apisession.mist_get(raw_url)
                raw_items = getattr(response, "data", response) or []
            else:
                response = list_func(apisession, current_org_id, limit=1000)
                raw_items = mistapi.get_all(response=response, mist_session=apisession) or []
            if not isinstance(raw_items, list):
                logging.debug("License endpoint returned non-list payload; normalizing to list")
                raw_items = [raw_items]
            if not raw_items:
                logging.info("No license records returned from canonical endpoint; writing empty OrgLicenses.csv")
                DataExporter.save_data_to_output([], filename, api_function_name="listOrgLicenses")  # type: ignore[no-untyped-call]
                return
            processed = DataProcessingUtils.flatten_nested_fields(raw_items)
            processed = DataProcessingUtils.escape_multiline(processed)  # type: ignore[no-untyped-call]
            DataExporter.save_data_to_output(processed, filename, api_function_name="listOrgLicenses")  # type: ignore[no-untyped-call]
            logging.info(f"Exported {len(processed)} license records to {filename}.")
        except Exception as e:
            logging.error(f"Failed to export licenses: {e}")
            try:
                DataExporter.save_data_to_output([], filename)  # type: ignore[no-untyped-call]
            except Exception:  # nosec B110
                pass
            raise

    @staticmethod
    def usage():  # type: ignore[no-untyped-def]
        """Export organization usage data to OrgUsage.csv."""
        logging.info("Starting export of organization license usage...")
        APIDataFetcher(
            title="Organization License Usage:",
            api_call=mistapi.api.v1.orgs.licenses.getOrgLicensesBySite,
            filename="OrgUsage",
            sort_key="site_id",
        ).execute()
        logging.info(" License usage data exported to OrgUsage")
        print(" License usage data exported to OrgUsage")


class SelfExportUtils:
    """
    Authenticated Self / Account Export Utilities

    Exports data scoped to the currently authenticated admin account rather
    than an org or site. Handles self audit logs and similar account-level
    read operations.
    """

    @staticmethod
    def audit_logs() -> None:  # type: ignore[no-untyped-def]
        """Export audit log of changes made by the authenticated admin account to SelfAuditLogs.csv."""
        logging.info("Starting export of self (admin account) audit logs...")  # Log before operation
        filename = "SelfAuditLogs.csv"  # Output filename for self audit log entries
        try:
            hours = TimeUtils.get_dynamic_lookback_hours(24, 1)  # Use same lookback window as other audit log exports
            TimeUtils.log_dynamic_lookback("self audit logs export", hours)  # Log lookback window selection
            logging.info("Fetching self audit logs for last %d hours...", hours)  # Log before API call
            response = mistapi.api.v1.self.logs.listSelfAuditLogs(  # Call Mist API for admin account audit log
                apisession,
                duration=f"{hours}h",  # Limit results to the dynamic lookback window
                limit=1000,  # Request large page to minimise pagination round-trips
            )
            logging.debug("Raw API response received for self audit logs")  # Log after API call
            rows = mistapi.get_all(response=response, mist_session=apisession)  # Paginate through all results
            logging.debug("Received %d self audit log records after pagination", len(rows))  # Log record count
            if not rows:  # No data returned — write empty output rather than failing silently
                logging.warning(
                    "No self audit log records returned for the last %d hours", hours
                )  # Warn on empty result
                DataExporter.save_data_to_output([], filename)  # Write empty file to signal successful run
                return
            rows = DataProcessingUtils.flatten_nested_fields(rows)  # Flatten nested change-detail dicts for CSV
            DataExporter.save_data_to_output(
                rows, filename, api_function_name="listSelfAuditLogs"
            )  # Write to configured backend
            logging.info("Exported %d self audit log records to %s", len(rows), filename)  # Log success
        except Exception as exception:  # Catch any API or processing error
            logging.error("Failed to export self audit logs: %s", exception, exc_info=True)  # Log full traceback


