class _LegacyWAN2MigrationManager:
    """
    Manages WAN2 interface variable migration for gateway templates and sites.

    Consolidates Menu Options 103 and 104:
    - set_site_variable(): Set wan2_interface site variable across sites (Menu 103)
    - update_templates(): Migrate gateway templates to use {{wan2_interface}} variable (Menu 104)

    Both operations support bidirectional migration (apply/revert) and preserve device-level
    static IP overrides by properly handling port_config keys.
    """

    def __init__(self):  # type: ignore[no-untyped-def]
        """Initialize the WAN2 migration manager."""
        self.org_id = ConfigUtils.get_cached_or_prompted_org_id()
        self.sites = []
        self.gateway_configs = []
        self.template_data = []
        self.site_to_template_id = {}
        self.template_port_configs = {}
        self.site_overrides_map = {}

    def set_site_variable(self):  # type: ignore[no-untyped-def]
        """
        Menu #149: Set WAN2 Interface Site Variable.

        Creates and sets the {{wan2_interface}} site variable to 'ge-0/0/1' across selected sites.
        Reports sites with WAN2 port overrides requiring manual review.
        """
        self._display_site_variable_header()  # type: ignore[no-untyped-call]

        if not self._load_required_data():
            return

        sites_to_configure = self._get_site_selection()
        if not sites_to_configure:
            return

        sites_to_configure = self._filter_excluded_sites(sites_to_configure)
        if not sites_to_configure:
            return

        if not self._confirm_site_variable_operation(len(sites_to_configure)):
            return

        self._build_override_detection_map()  # type: ignore[no-untyped-call]
        results = self._process_sites_for_variable(sites_to_configure)
        self._generate_site_variable_report(results)

    def _display_site_variable_header(self):  # type: ignore[no-untyped-def]
        """Display operation header for Menu #149."""
        print("\n  Set WAN2 Interface Site Variable")
        print("=" * 70)
        print("  This operation will set the 'wan2_interface' site variable to 'ge-0/0/1'")
        print("  across selected sites, preparing them for template-based WAN migration.")
        print("=" * 70)
        logging.info("Menu #149: Set WAN2 Interface Site Variable operation started")

    def _load_required_data(self) -> bool:
        """Load site and gateway configuration data. Returns True on success."""
        print("\n  Preparing site and gateway configuration data...")
        CacheUtils.check_and_generate_csv("SiteList.csv", OrgSiteExporter.sites)
        CacheUtils.check_and_generate_csv("AllSiteGatewayConfigs.csv", GatewayExportUtils.device_configs)
        CacheUtils.check_and_generate_csv("OrgGatewayTemplates.csv", GatewayExportUtils.templates)

        site_list_path = FilePathUtils.get_csv_path("SiteList.csv")
        with open(site_list_path, encoding="utf-8") as file_handle:
            self.sites = list(csv.DictReader(file_handle))

        if not self.sites:
            print(" No sites found in organization.")
            logging.warning("No sites available for WAN2 variable assignment")
            return False

        return True

    def _get_site_selection(self) -> list[dict[str, Any]]:
        """Prompt user for site selection. Returns selected sites or empty list."""
        logging.info(  # Entry envelope — log scope before showing selection menu to user
            "Entering WAN2MigrationManager._get_site_selection: %s sites available",
            len(self.sites),
        )
        print(f"\n  Found {len(self.sites)} sites in organization")
        print("  Site Selection:")
        print("   1. Select individual sites")
        print("   2. All sites in organization")
        print("   3. Cancel")

        selection_choice = InputUtils.safe_input(
            "\n  Choose selection method (1-3): ",
            context="wan2_site_selection_method",
        ).strip()

        if selection_choice == "1":
            result = self._select_individual_sites()  # Delegate individual selection to helper
            logging.info(  # Exit envelope on individual selection
                "Exiting WAN2MigrationManager._get_site_selection: individual selection returned %s sites",
                len(result),
            )
            return result
        elif selection_choice == "2":
            all_sites = self.sites.copy()  # Return copy of all sites to avoid mutation
            logging.info(  # Exit envelope on all-sites selection
                "Exiting WAN2MigrationManager._get_site_selection: all-sites selection returned %s sites",
                len(all_sites),
            )
            return all_sites
        else:
            print(" Operation cancelled.")
            logging.info("Menu #149 cancelled by user")
            logging.info(  # Exit envelope on cancel
                "Exiting WAN2MigrationManager._get_site_selection: cancelled by user"
            )
            return []

    def _select_individual_sites(self) -> list[dict[str, Any]]:
        """Display site list and get individual selections."""
        print("\n  Available Sites:")
        for index, site in enumerate(self.sites, start=1):
            site_name = site.get("name", "Unnamed Site")
            site_id = site.get("id", "")
            print(f"   [{index}] {site_name} ({site_id})")

        print("\n  Enter site numbers to configure (comma-separated, e.g., 1,3,5):")
        site_indices_input = InputUtils.safe_input("  Site numbers: ", context="wan2_site_index_selection").strip()

        try:
            selected_indices = [int(idx.strip()) - 1 for idx in site_indices_input.split(",")]
            return [self.sites[idx] for idx in selected_indices if 0 <= idx < len(self.sites)]
        except (ValueError, IndexError) as error:
            print(f" Invalid site selection: {error}")
            logging.error(f"Invalid site selection in Menu #149: {error}")
            return []

    def _filter_excluded_sites(self, sites_to_configure: list[dict[str, Any]]) -> list[dict[str, Any]]:
        """Filter out excluded sites from configuration list based on MIST_SITE_EXCLUDE_PREFIX."""
        if not MIST_SITE_EXCLUDE_PREFIX:
            return sites_to_configure  # No prefix configured, include all sites

        original_count = len(sites_to_configure)
        filtered_sites = [
            site for site in sites_to_configure if not site.get("name", "").startswith(MIST_SITE_EXCLUDE_PREFIX)
        ]
        filtered_count = original_count - len(filtered_sites)

        if filtered_count > 0:
            print(f"\n  !? SECURITY: Excluded {filtered_count} '{MIST_SITE_EXCLUDE_PREFIX}*' sites from configuration")
            logging.info(
                f"Menu #149: Excluded {filtered_count} sites matching prefix '{MIST_SITE_EXCLUDE_PREFIX}' from WAN2 variable operation"  # noqa: E501
            )

        if not filtered_sites:
            print(f" No sites remaining after filtering '{MIST_SITE_EXCLUDE_PREFIX}*' sites.")
            logging.warning(
                f"Menu #149: All selected sites matched exclude prefix '{MIST_SITE_EXCLUDE_PREFIX}' - operation cancelled"  # noqa: E501
            )

        return filtered_sites

    def _confirm_site_variable_operation(self, site_count: int) -> bool:
        """Confirm the site variable operation with user."""
        logging.info(  # Entry envelope — log scope before destructive confirmation prompt
            "Entering WAN2MigrationManager._confirm_site_variable_operation: %s sites pending",
            site_count,
        )
        print(f"\n  Will configure {site_count} sites with wan2_interface variable.")
        confirm = (
            InputUtils.safe_input(
                "\n  Proceed with setting site variables? (yes/no): ",
                context="wan2_site_variable_confirm",
            )
            .strip()
            .lower()
        )

        if confirm not in ["yes", "y"]:
            print(" Operation cancelled.")
            logging.info("Menu #149 cancelled by user at confirmation prompt")
            logging.info(  # Exit envelope on cancel
                "Exiting WAN2MigrationManager._confirm_site_variable_operation: result=cancelled"
            )
            return False
        logging.info(  # Exit envelope on confirm
            "Exiting WAN2MigrationManager._confirm_site_variable_operation: result=confirmed for %s sites",
            site_count,
        )
        return True

    def _build_override_detection_map(self):  # type: ignore[no-untyped-def]
        """Build map of sites with WAN2 port overrides for analysis."""
        self._load_gateway_configs()  # type: ignore[no-untyped-call]
        self._load_template_configs()  # type: ignore[no-untyped-call]
        self._build_site_to_template_mapping()  # type: ignore[no-untyped-call]
        self._extract_template_port_configs()  # type: ignore[no-untyped-call]
        self._detect_device_overrides()  # type: ignore[no-untyped-call]

    def _load_gateway_configs(self):  # type: ignore[no-untyped-def]
        """Load gateway device configurations from CSV."""
        gateway_configs_path = FilePathUtils.get_csv_path("AllSiteGatewayConfigs.csv")
        with open(gateway_configs_path, encoding="utf-8") as file_handle:
            self.gateway_configs = list(csv.DictReader(file_handle))

    def _load_template_configs(self):  # type: ignore[no-untyped-def]
        """Load gateway template configurations from CSV."""
        template_configs_path = FilePathUtils.get_csv_path("OrgGatewayTemplates.csv")
        with open(template_configs_path, encoding="utf-8") as file_handle:
            self.template_data = list(csv.DictReader(file_handle))

    def _build_site_to_template_mapping(self):  # type: ignore[no-untyped-def]
        """Build mapping from site_id to gateway template_id."""
        for site in self.sites:
            site_id = site.get("id", "").strip()
            template_id = site.get("gatewaytemplate_id", "").strip()
            if site_id and template_id:
                self.site_to_template_id[site_id] = template_id
        logging.info(f"Mapped {len(self.site_to_template_id)} sites to gateway templates")

    def _extract_template_port_configs(self):  # type: ignore[no-untyped-def]
        """Extract IP configuration type from templates for ge-0/0/1 port."""
        for template_row in self.template_data:
            template_id = template_row.get("id", "").strip()
            if not template_id:
                continue

            ip_config = self._parse_template_ip_config(template_row)
            self.template_port_configs[template_id] = ip_config

        logging.info(f"Loaded port IP configs for {len(self.template_port_configs)} templates")

    def _parse_template_ip_config(self, template_row: dict[str, Any]) -> dict[str, str]:
        """Parse IP configuration from template row."""
        ip_config_raw = template_row.get("port_config_ge-0/0/1_ip_config", "").strip()
        result = {"ip_type": "not_configured", "ip": "", "netmask": "", "gateway": ""}

        if not ip_config_raw:
            return result

        try:
            ip_config_data = json.loads(ip_config_raw)
            result["ip_type"] = ip_config_data.get("type", "").lower() or "not_configured"
            if result["ip_type"] == "static":
                result["ip"] = ip_config_data.get("ip", "")
                result["netmask"] = ip_config_data.get("netmask", "")
                result["gateway"] = ip_config_data.get("gateway", "")
        except json.JSONDecodeError as error:
            logging.warning(f"Failed to parse template IP config: {error}")
            result["ip_type"] = "parse_error"

        return result

    def _detect_device_overrides(self):  # type: ignore[no-untyped-def]
        """Detect devices with WAN2 port overrides and classify severity."""
        for config_row in self.gateway_configs:
            site_id = config_row.get("site_id", "").strip()
            device_name = config_row.get("name", "").strip()

            override_info = self._analyze_device_override(config_row, site_id)
            if override_info:
                if site_id not in self.site_overrides_map:
                    self.site_overrides_map[site_id] = []
                self.site_overrides_map[site_id].append({"device_name": device_name, **override_info})

    def _analyze_device_override(self, config_row: dict[str, Any], site_id: str) -> dict[str, Any] | None:
        """Analyze a device config for WAN2 port overrides. Returns override info or None."""
        wan2_fields = self._get_wan2_override_fields(config_row)
        has_override = self._check_has_meaningful_override(config_row, wan2_fields)

        if not has_override:
            return None

        device_ip_info = self._extract_device_ip_config(config_row)
        template_ip_type = self._get_template_ip_type_for_site(site_id, device_ip_info.get("port_identifier", ""))
        severity = self._classify_override_severity(template_ip_type, device_ip_info.get("ip_type", ""))

        return {
            "port_identifier": device_ip_info.get("port_identifier", "ge-0/0/1"),
            "template_ip_type": template_ip_type.upper(),
            "device_ip_type": device_ip_info.get("ip_type", "").upper() or "NOT_CONFIGURED",
            "device_static_ip": device_ip_info.get("ip", ""),
            "device_netmask": device_ip_info.get("netmask", ""),
            "device_gateway": device_ip_info.get("gateway", ""),
            "override_severity": severity,
            "ip_type_conflict": severity in ["CRITICAL", "WARNING"],
        }

    def _get_wan2_override_fields(self, config_row: dict[str, Any]) -> list[str]:
        """Get list of WAN2-related port_config fields from config row."""
        return [
            col
            for col in config_row
            if col.startswith("port_config_ge-0/0/1_")
            or col.startswith("port_config_ge-0/0/1.")
            or col.startswith("port_config_{{wan2_interface}}_")
            or col.startswith("port_config_{{wan2_interface}}.")
        ]

    def _check_has_meaningful_override(self, config_row: dict[str, Any], fields: list[str]) -> bool:
        """Check if config row has meaningful WAN2 overrides (excluding VPN paths)."""
        return any(
            config_row.get(field, "").strip().lower() not in ["", "null", "none"]
            for field in fields
            if "_vpn_paths_" not in field
        )

    def _extract_device_ip_config(self, config_row: dict[str, Any]) -> dict[str, str]:
        """Extract IP configuration from device config row."""
        subinterface_configs = self._find_subinterface_ip_configs(config_row)
        if subinterface_configs:
            return subinterface_configs[0]

        return self._extract_base_port_ip_config(config_row)

    def _find_subinterface_ip_configs(self, config_row: dict[str, Any]) -> list[dict[str, str]]:
        """Find and parse subinterface IP configurations."""
        configs = []
        for col in config_row:
            if not (
                (col.startswith("port_config_ge-0/0/1.") or col.startswith("port_config_{{wan2_interface}}."))
                and col.endswith("_ip_config_type")
            ):
                continue

            subif_ip_type = config_row.get(col, "").strip().lower()
            if not subif_ip_type:
                continue

            subif_name = col.replace("port_config_", "").replace("_ip_config_type", "")
            ip_col_base = f"port_config_{subif_name}_ip_config"

            configs.append(
                {
                    "port_identifier": subif_name,
                    "ip_type": subif_ip_type,
                    "ip": config_row.get(f"{ip_col_base}_ip", "").strip(),
                    "netmask": config_row.get(f"{ip_col_base}_netmask", "").strip(),
                    "gateway": config_row.get(f"{ip_col_base}_gateway", "").strip(),
                }
            )

        return configs

    def _extract_base_port_ip_config(self, config_row: dict[str, Any]) -> dict[str, str]:
        """Extract base port (ge-0/0/1) IP configuration from device config."""
        result = {"port_identifier": "ge-0/0/1", "ip_type": "", "ip": "", "netmask": "", "gateway": ""}
        ip_config_raw = config_row.get("port_config_ge-0/0/1_ip_config", "").strip()

        if not ip_config_raw:
            return result

        try:
            ip_data = json.loads(ip_config_raw)
            result["ip_type"] = ip_data.get("type", "").lower()
            if result["ip_type"] == "static":
                result["ip"] = ip_data.get("ip", "")
                result["netmask"] = ip_data.get("netmask", "")
                result["gateway"] = ip_data.get("gateway", "")
        except json.JSONDecodeError:
            result["ip_type"] = "parse_error"

        return result

    def _get_template_ip_type_for_site(self, site_id: str, port_identifier: str) -> str:
        """Get the template IP type for a site, checking subinterface if needed."""
        template_id = self.site_to_template_id.get(site_id, "")
        template_config = self.template_port_configs.get(template_id, {})
        template_ip_type = template_config.get("ip_type", "unknown")

        if "." in port_identifier:
            for template_row in self.template_data:
                if template_row.get("id", "").strip() == template_id:
                    subif_col = f"port_config_{port_identifier}_ip_config_type"
                    subif_type = template_row.get(subif_col, "").strip().lower()
                    if subif_type:
                        return subif_type  # type: ignore[no-any-return]
                    break

        return template_ip_type  # type: ignore[no-any-return]

    def _classify_override_severity(self, template_ip_type: str, device_ip_type: str) -> str:
        """Classify override severity based on IP type mismatch."""
        if template_ip_type == "dhcp" and device_ip_type == "static":
            return "CRITICAL"
        elif template_ip_type == "static" and device_ip_type == "dhcp":
            return "WARNING"
        elif template_ip_type == device_ip_type and device_ip_type in ["dhcp", "static"]:
            return "INFO"
        return "UNKNOWN"

    def _process_sites_for_variable(self, sites_to_configure: list[dict[str, Any]]) -> list[dict[str, Any]]:
        """Process each site to set the wan2_interface variable."""
        results = []
        print("\n  Processing sites...")

        for site in tqdm(sites_to_configure, desc="Configuring sites", unit="site"):  # type: ignore[no-untyped-call]
            if ConfigUtils.check_stop_signal():
                break
            result = self._set_variable_for_site(site)
            results.append(result)

        return results

    def _set_variable_for_site(self, site: dict[str, Any]) -> dict[str, Any]:
        """Set wan2_interface variable for a single site."""
        site_id = site.get("id", "")
        site_name = site.get("name", "Unnamed Site")

        result = self._initialize_site_result(site_id, site_name)
        self._add_override_info_to_result(result, site_id)

        try:
            self._update_site_settings(site_id, site_name, result)
        except Exception as error:
            result["status"] = "ERROR"
            result["error"] = str(error)
            logging.error(f"Error setting variable for site {site_name}: {error}")
            logging.error(traceback.format_exc())

        return result

    def _initialize_site_result(self, site_id: str, site_name: str) -> dict[str, Any]:
        """Initialize result dictionary for a site."""
        return {
            "site_id": site_id,
            "site_name": site_name,
            "variable_set": False,
            "has_overrides": False,
            "override_devices": [],
            "critical_override_count": 0,
            "warning_override_count": 0,
            "info_override_count": 0,
            "total_override_count": 0,
            "status": "",
            "error": "",
        }

    def _add_override_info_to_result(self, result: dict[str, Any], site_id: str):  # type: ignore[no-untyped-def]
        """Add override detection info to result dictionary."""
        if site_id not in self.site_overrides_map:
            return

        result["has_overrides"] = True
        override_details = self.site_overrides_map[site_id]
        result["override_devices"] = [d["device_name"] for d in override_details]

        critical = [d for d in override_details if d["override_severity"] == "CRITICAL"]
        warning = [d for d in override_details if d["override_severity"] == "WARNING"]
        info = [d for d in override_details if d["override_severity"] == "INFO"]

        result["critical_override_count"] = len(critical)
        result["warning_override_count"] = len(warning)
        result["info_override_count"] = len(info)
        result["total_override_count"] = len(override_details)
        result["override_details"] = self._format_override_details(override_details)

    def _format_override_details(self, override_details: list[dict[str, Any]]) -> str:
        """Format override details for CSV export."""
        summaries = []
        for detail in override_details:
            device = detail["device_name"]
            port = detail.get("port_identifier", "ge-0/0/1")
            severity = detail["override_severity"]
            template_ip = detail["template_ip_type"]
            device_ip = detail["device_ip_type"]
            static_ip = detail["device_static_ip"]
            netmask = detail["device_netmask"]

            if static_ip and netmask:
                summary = f"{device}@{port}({severity}:{template_ip}->{device_ip}:{static_ip}{netmask})"
            elif static_ip:
                summary = f"{device}@{port}({severity}:{template_ip}->{device_ip}:{static_ip})"
            else:
                summary = f"{device}@{port}({severity}:{template_ip}->{device_ip})"
            summaries.append(summary)

        return "; ".join(summaries)

    def _update_site_settings(self, site_id: str, site_name: str, result: dict[str, Any]):  # type: ignore[no-untyped-def]
        """Update site settings with wan2_interface variable."""
        logging.debug(f"Fetching current settings for site {site_name} ({site_id})")
        settings_resp = mistapi.api.v1.sites.setting.getSiteSetting(apisession, site_id)
        current_settings = settings_resp.data if hasattr(settings_resp, "data") else {}

        if not isinstance(current_settings, dict):
            current_settings = {}

        site_vars = current_settings.get("vars", {})
        if not isinstance(site_vars, dict):
            site_vars = {}

        site_vars["wan2_interface"] = "ge-0/0/1"
        current_settings["vars"] = site_vars

        logging.debug(f"Updating site settings for {site_name} with wan2_interface variable")
        update_resp = mistapi.api.v1.sites.setting.updateSiteSettings(apisession, site_id, body=current_settings)

        if update_resp.status_code == 200:
            result["variable_set"] = True
            result["status"] = "SUCCESS"
            logging.info(f"Successfully set wan2_interface variable for site {site_name}")
        else:
            result["status"] = "FAILED"
            result["error"] = f"API returned status {update_resp.status_code}"
            logging.error(f"Failed to set variable for site {site_name}: status {update_resp.status_code}")

    def _generate_site_variable_report(self, results: list[dict[str, Any]]):  # type: ignore[no-untyped-def]
        """Generate and save the site variable report."""
        report_data = self._build_report_data(results)
        output_file = "WAN2_SiteVariable_Report.csv"
        DataExporter.save_data_to_output(report_data, output_file)  # type: ignore[no-untyped-call]

        self._print_site_variable_summary(results, output_file)

    def _build_report_data(self, results: list[dict[str, Any]]) -> list[dict[str, Any]]:
        """Build report data from results."""
        report_data = []
        for result in results:
            requires_review = (
                "CRITICAL"
                if result.get("critical_override_count", 0) > 0
                else (
                    "WARNING"
                    if result.get("warning_override_count", 0) > 0
                    else ("INFO" if result.get("info_override_count", 0) > 0 else "No")
                )
            )

            report_data.append(
                {
                    "site_name": result["site_name"],
                    "site_id": result["site_id"],
                    "wan2_variable_set": "Yes" if result["variable_set"] else "No",
                    "status": result["status"],
                    "has_wan2_overrides": "Yes" if result["has_overrides"] else "No",
                    "total_override_count": result.get("total_override_count", 0),
                    "critical_override_count": result.get("critical_override_count", 0),
                    "warning_override_count": result.get("warning_override_count", 0),
                    "info_override_count": result.get("info_override_count", 0),
                    "override_devices": ", ".join(result["override_devices"]) if result["override_devices"] else "",
                    "override_details": result.get("override_details", ""),
                    "requires_manual_review": requires_review,
                    "error": result["error"],
                }
            )
        return report_data

    def _print_site_variable_summary(self, results: list[dict[str, Any]], output_file: str):  # type: ignore[no-untyped-def]
        """Print summary of site variable operation."""
        success_count = sum(1 for r in results if r["variable_set"])
        override_count = sum(1 for r in results if r["has_overrides"])
        critical_sites = sum(1 for r in results if r.get("critical_override_count", 0) > 0)
        warning_sites = sum(1 for r in results if r.get("warning_override_count", 0) > 0)
        info_sites = sum(
            1
            for r in results
            if r.get("has_overrides")
            and r.get("critical_override_count", 0) == 0
            and r.get("warning_override_count", 0) == 0
        )

        print("\n  Configuration Complete!")
        print("=" * 70)
        print(f"  Sites Processed: {len(results)}")
        print(f"  Variables Set: {success_count}")
        print(f"  Sites with WAN2 Overrides: {override_count}")
        print(f"    -> CRITICAL (DHCP->Static IP conflicts): {critical_sites}")
        print(f"    -> WARNING (Static->DHCP conflicts): {warning_sites}")
        print(f"    -> INFO (Same IP type, other overrides): {info_sites}")
        print(f"\n  Report saved to: {output_file}")
        print("=" * 70)

        self._print_severity_warnings(critical_sites, warning_sites, info_sites)

        logging.info(f"Menu #149 complete: {success_count}/{len(results)} sites configured")
        logging.info(f"Override breakdown - CRITICAL: {critical_sites}, WARNING: {warning_sites}, INFO: {info_sites}")

    def _print_severity_warnings(self, critical_sites: int, warning_sites: int, info_sites: int):  # type: ignore[no-untyped-def]
        """Print severity-specific warnings."""
        if critical_sites > 0:
            print(f"\n  !? CRITICAL ATTENTION: {critical_sites} sites have DHCP->Static IP conflicts")
            print("  Template specifies DHCP but devices use locally unique static IPs")
            print("  These MUST be manually reviewed before template migration (Menu #163)")
            print("  Static IPs will be lost if template DHCP is applied without device overrides")
            print("  Check 'override_details' column for device names and static IP addresses")

        if warning_sites > 0:
            print(f"\n  ! WARNING: {warning_sites} sites have Static->DHCP conflicts")
            print("  Template specifies Static IP but devices configured for DHCP")
            print("  Review recommended before template migration")

        if info_sites > 0:
            print(f"\n  INFO: {info_sites} sites have same-IP-type overrides (likely safe)")
            print("  Template and device use same IP configuration type (both DHCP or both Static)")
            print("  Overrides may be for description, usage, or other non-critical fields")


# ============================================================================
# WAN2 MIGRATION MANAGER CLASS (delegated)
# ============================================================================
class WAN2MigrationManager:
    """Delegation wrapper for extracted WAN2 migration manager implementation."""

    def __init__(self):  # type: ignore[no-untyped-def]
        """Initialize delegated WAN2 manager with runtime dependencies."""
        from src.gateway import wan2_migration_manager as wan2_module  # noqa: PLC0415,I001

        wan2_module.configure_wan2_migration_dependencies(
            apisession_dependency=apisession,
            config_utils=ConfigUtils,
            cache_utils=CacheUtils,
            org_site_exporter=OrgSiteExporter,
            gateway_export_utils=GatewayExportUtils,
            file_path_utils=FilePathUtils,
            input_utils=InputUtils,
            data_exporter=DataExporter,
            mistapi_dependency=mistapi,
            site_exclude_prefix=MIST_SITE_EXCLUDE_PREFIX,
        )
        self._impl = wan2_module.WAN2MigrationManager()

    def set_site_variable(self):  # type: ignore[no-untyped-def]
        """Menu #149 delegated entrypoint."""
        return self._impl.set_site_variable()

    def __getattr__(self, name):  # type: ignore[no-untyped-def]
        """Proxy attribute access to the extracted implementation."""
        return getattr(self._impl, name)  # Delegate to real impl for test compat


# ============================================================================
# ORG CONFIG MIGRATION MANAGER CLASS
# ============================================================================
class OrgConfigMigrationManager:
    """
    Export and import org-level WAN/gateway configuration for cross-org migration.

    Menu 176: Export 6 config types to a timestamped JSON bundle.
    Menu 177: Import a bundle into the current org with conflict detection.
    """

    STRIP_FIELDS = frozenset(  # Fields to strip before import
        {"id", "org_id", "created_time", "modified_time", "for_site"}
    )

    CONFIG_TYPES = [
        {
            "key": "networks",  # Internal key for this config type in the bundle
            "list_fn": "mistapi.api.v1.orgs.networks.listOrgNetworks",  # Dotted path to list API
            "create_fn": "mistapi.api.v1.orgs.networks.createOrgNetwork",  # Dotted path to create API
            "import_order": 0,  # Import first -- no dependencies on other types
            "display_name": "Networks",  # User-facing label for menus and reports
            "conflict_check": "subnet",  # Enables IP/subnet overlap detection
        },
        {
            "key": "services",  # Internal key for services in the bundle
            "list_fn": "mistapi.api.v1.orgs.services.listOrgServices",  # Dotted path to list API
            "create_fn": "mistapi.api.v1.orgs.services.createOrgService",  # Dotted path to create API
            "import_order": 0,  # Import first -- no dependencies on other types
            "display_name": "Services",  # User-facing label for menus and reports
            "conflict_check": "addresses",  # Enables IP address overlap detection
        },
        {
            "key": "vpns",  # Internal key for VPNs in the bundle
            "list_fn": "mistapi.api.v1.orgs.vpns.listOrgVpns",  # Dotted path to list API
            "create_fn": "mistapi.api.v1.orgs.vpns.createOrgVpn",  # Dotted path to create API
            "import_order": 1,  # Import second -- depends on networks
            "display_name": "VPNs",  # User-facing label for menus and reports
        },
        {
            "key": "gateway_templates",  # Internal key for gateway templates in the bundle
            "list_fn": "mistapi.api.v1.orgs.gatewaytemplates.listOrgGatewayTemplates",  # Dotted path to list API
            "create_fn": "mistapi.api.v1.orgs.gatewaytemplates.createOrgGatewayTemplate",  # Dotted path to create API
            "import_order": 1,  # Import second -- depends on networks and VPNs
            "display_name": "Gateway Templates",  # User-facing label for menus and reports
        },
        {
            "key": "device_profiles",  # Internal key for device profiles in the bundle
            "list_fn": "mistapi.api.v1.orgs.deviceprofiles.listOrgDeviceProfiles",  # Dotted path to list API
            "create_fn": "mistapi.api.v1.orgs.deviceprofiles.createOrgDeviceProfile",  # Dotted path to create API
            "import_order": 2,  # Import last -- depends on gateway templates
            "display_name": "Device Profiles",  # User-facing label for menus and reports
            "list_kwargs": {"type": "gateway"},  # Filter to gateway profiles only
        },
        {
            "key": "service_policies",  # Internal key for service policies in the bundle
            "list_fn": "mistapi.api.v1.orgs.servicepolicies.listOrgServicePolicies",  # Dotted path to list API
            "create_fn": "mistapi.api.v1.orgs.servicepolicies.createOrgServicePolicy",  # Dotted path to create API
            "import_order": 2,  # Import last -- depends on services
            "display_name": "Service Policies",  # User-facing label for menus and reports
        },
    ]

    def __init__(self, session, org_id_fn, safe_input_fn):  # type: ignore[no-untyped-def]
        """Initialize with API session, org_id resolver, and safe_input function."""
        self.session = session  # Authenticated mistapi session for API calls
        self.org_id_fn = org_id_fn  # Callable that returns current org_id (may prompt user)
        self.safe_input_fn = safe_input_fn  # EOF-safe input wrapper for SSH/container contexts
        self.org_id = ""  # Resolved org ID, set during export_config or import_config
        self._remap_table: dict[str, str] = {}  # Maps source object IDs to destination IDs
        self._existing: dict[str, list] = {}  # type: ignore[type-arg] # Cached destination org objects for conflict detection

    # ------------------------------------------------------------------
    # Public entry points
    # ------------------------------------------------------------------

    def export_config(self) -> None:
        """Menu 176: Export org WAN/gateway config to a JSON bundle."""
        logging.info("Menu 176: Starting org config export")  # Log operation start for traceability
        self.org_id = self.org_id_fn()  # Resolve current org ID from cache or user prompt
        org_name = self._get_org_name()  # Fetch human-readable org name for bundle metadata
        print(f"\n  Exporting WAN/Gateway config from org: {org_name}")  # User feedback

        results = self._fetch_all_types()  # Fetch all 6 config types from the API
        bundle = self._build_export_bundle(results, org_name)  # Wrap results with metadata
        filepath = self._save_bundle_to_file(bundle, org_name)  # Write bundle to data/ directory
        self._display_export_summary(bundle, filepath)  # Show summary table to user
        logging.info("Menu 176: Export complete, saved to %s", filepath)  # Log completion

    def _fetch_all_types(self) -> dict[str, list]:  # type: ignore[type-arg]
        """Fetch all 6 config types and return as a keyed dictionary."""
        results: dict[str, list] = {}  # type: ignore[type-arg] # Accumulates fetched objects by type key
        for config_type in self.CONFIG_TYPES:  # Iterate each registered config type
            items = self._fetch_config_type(config_type)  # Fetch objects from Mist API
            results[config_type["key"]] = items  # Store under the type's key name
        return results  # Return complete results dict

    def import_config(self) -> None:
        """Menu 177: Import a JSON bundle into the current org."""
        logging.info("Menu 177: Starting org config import")  # Log operation start for traceability
        self.org_id = self.org_id_fn()  # Resolve destination org ID from cache or user prompt
        filepath = self._select_import_file()  # Let user pick from available export bundles
        if not filepath:  # User cancelled or no files found
            return

        bundle = self._load_and_validate_bundle(filepath)  # Parse JSON and validate structure
        if not bundle:  # Invalid or unreadable bundle
            return

        self._display_bundle_preview(bundle)  # Show what the bundle contains before proceeding
        dry_run = self._prompt_dry_run()  # Ask if user wants preview-only mode
        if not dry_run and not self._confirm_import():  # Require typed IMPORT for real operations
            return

        self._fetch_existing_objects()  # Cache destination org objects for conflict detection
        results = self._execute_import(bundle, dry_run)  # Run the dependency-ordered import
        self._display_import_report(results)  # Show final summary of what happened
        logging.info("Menu 177: Import complete, %s objects processed", len(results))  # Log completion

    # ------------------------------------------------------------------
    # Export helpers
    # ------------------------------------------------------------------

    def _get_org_name(self) -> str:
        """Fetch organization name from the API."""
        logging.info("Fetching org name for org %s", self.org_id)  # Log before API call
        try:
            response = mistapi.api.v1.orgs.orgs.getOrg(self.session, self.org_id)  # Query Mist API for org details
            if hasattr(response, "data") and response.data:  # Verify response has data attribute
                name = response.data.get("name", "Unknown")  # Extract org name from response
                logging.debug("Org name resolved: %s", name)  # Log resolved name
                return name  # type: ignore[no-any-return] # Return org name string
        except Exception as error:  # Catch network/auth errors gracefully
            logging.warning("Could not fetch org name: %s", error)  # Log warning with error details
        return "Unknown"  # Fallback when API call fails

    def _resolve_api_fn(self, dotted_path: str):  # type: ignore[no-untyped-def]
        """Resolve a dotted string like 'mistapi.api.v1.orgs.networks.listOrgNetworks' to a callable."""
        parts = dotted_path.split(".")  # Split dotted path into module segments
        current = mistapi  # Start from the top-level mistapi module
        for part in parts[1:]:  # Walk down the module tree, skipping 'mistapi' prefix
            current = getattr(current, part)  # Resolve each nested attribute
        return current  # Return the final callable function

    def _fetch_config_type(self, config_type: dict) -> list:  # type: ignore[type-arg]
        """Fetch all objects of a single config type from the API."""
        display_name = config_type["display_name"]  # Human-readable name for logging
        logging.info("Fetching %s from org %s", display_name, self.org_id)  # Log before API call
        try:
            list_fn = self._resolve_api_fn(config_type["list_fn"])  # Resolve dotted path to callable
            kwargs = config_type.get("list_kwargs", {})  # Extra kwargs like type=gateway for device profiles
            response = list_fn(self.session, self.org_id, limit=1000, **kwargs)  # Call Mist API with pagination limit
            items = self._extract_response_data(response)  # Extract list data from response wrapper
            print(f"    {display_name}: {len(items)} objects")  # User feedback showing count
            logging.debug("Fetched %s %s objects", len(items), display_name)  # Log result count
            return items  # Return list of config objects
        except Exception as error:  # Catch API errors without crashing the entire export
            print(f"  X {display_name}: Error - {error}")  # User feedback showing failure
            logging.error("Failed to fetch %s: %s", display_name, error)  # Log error with context
            return []  # Return empty list so other types can still proceed

    def _extract_response_data(self, response) -> list:  # type: ignore[type-arg, no-untyped-def]
        """Extract list data from an API response, handling pagination."""
        if hasattr(response, "data") and isinstance(response.data, list):  # Check for direct list response
            return response.data  # type: ignore[no-any-return] # Return data directly if already a list
        items = mistapi.get_all(response=response, mist_session=self.session)  # Handle paginated responses
        return items if items else []  # Return items or empty list if None

    def _build_export_bundle(self, results: dict, org_name: str) -> dict:  # type: ignore[type-arg]
        """Build the export bundle with metadata wrapper."""
        counts = {key: len(items) for key, items in results.items()}  # Count objects per type for metadata
        metadata = {
            "source_org_id": self.org_id,  # Track which org this data came from
            "source_org_name": org_name,  # Human-readable org name for import preview
            "export_timestamp": datetime.now(UTC).isoformat(),  # UTC timestamp
            "schema_version": "1.0",  # Bundle format version for future compatibility
            "object_counts": counts,  # Per-type counts for quick inspection
        }
        bundle: dict = {"metadata": metadata}  # type: ignore[type-arg] # Start bundle with metadata section
        bundle.update(results)  # Add all config type data to the bundle
        return bundle  # Return complete export bundle

    def _save_bundle_to_file(self, bundle: dict, org_name: str) -> str:  # type: ignore[type-arg]
        """Save the export bundle as indented JSON to data/ directory."""
        safe_name = "".join(  # Sanitize org name for safe filename
            c if c.isalnum() or c in "-_" else "_" for c in org_name
        )
        timestamp = datetime.now(UTC).strftime("%Y%m%d_%H%M%S")  # UTC timestamp for uniqueness
        filename = f"OrgConfig_Export_{safe_name}_{timestamp}.json"  # Construct descriptive filename
        filepath = os.path.join("data", filename)  # Use os.path.join for cross-platform paths
        logging.info("Saving export bundle to %s", filepath)  # Log before file write
        with open(filepath, "w", encoding="utf-8") as output_file:  # Open file with UTF-8 encoding
            json.dump(bundle, output_file, indent=2, default=str)  # Write indented JSON for readability
        logging.debug("Export bundle saved, %s bytes", os.path.getsize(filepath))  # Log file size after write
        return filepath  # Return path for summary display

    def _display_export_summary(self, bundle: dict, filepath: str) -> None:  # type: ignore[type-arg]
        """Print a summary table of the export results."""
        counts = bundle["metadata"]["object_counts"]  # Extract per-type counts from metadata
        total = sum(counts.values())  # Calculate total objects across all types
        print(f"\n  Export Summary - saved to {filepath}")  # Show output file location
        print("  " + "-" * 40)  # Visual separator for table
        for config_type in self.CONFIG_TYPES:  # Iterate types in registry order
            key = config_type["key"]  # Get the bundle key for this type
            print(f"    {config_type['display_name']:<25} {counts.get(key, 0):>5}")  # Aligned count column
        print("  " + "-" * 40)  # Visual separator for totals row
        print(f"    {'TOTAL':<25} {total:>5}")  # Grand total

    # ------------------------------------------------------------------
    # Import helpers
    # ------------------------------------------------------------------

    def _select_import_file(self) -> str:
        """List available export bundles and let the user pick one."""
        import glob  # Local import -- only needed for this method

        pattern = os.path.join("data", "OrgConfig_Export_*.json")  # Glob pattern for export bundles
        files = sorted(glob.glob(pattern), reverse=True)  # Most recent files first
        logging.debug("Found %s export bundles in data/", len(files))  # Log discovery count
        if not files:  # No export bundles exist yet
            print("\n  No export bundles found in data/ directory.")  # User feedback
            print("  Run Menu 176 first to export config from a source org.")  # Guidance
            return ""  # Signal no selection made

        if len(files) == 1:  # Auto-select when only one file exists
            print(f"\n  Found 1 export bundle: {os.path.basename(files[0])}")  # Confirm auto-selection
            return files[0]  # Return the only available file

        return self._prompt_file_selection(files)  # Multiple files -- let user choose

    def _prompt_file_selection(self, files: list) -> str:  # type: ignore[type-arg]
        """Display numbered file list and get user selection."""
        print("\n  Available export bundles:")  # Section header
        for index, filepath in enumerate(files, 1):  # Number each file starting at 1
            print(f"    {index}. {os.path.basename(filepath)}")  # Show filename only, not full path

        choice = self.safe_input_fn(  # EOF-safe input for SSH/container contexts
            f"\n  Select bundle [1-{len(files)}]: ",
            context="import_file_selection",
        )
        try:
            selected = int(choice) - 1  # Convert 1-based user input to 0-based index
            if 0 <= selected < len(files):  # Validate index is within range
                return files[selected]  # Return the selected file path
        except (ValueError, IndexError):  # Handle non-numeric or out-of-range input
            pass
        print("  Invalid selection.")  # User feedback for bad input
        return ""  # Signal no valid selection

    def _load_and_validate_bundle(self, filepath: str) -> dict | None:  # type: ignore[type-arg]
        """Parse and validate the export bundle JSON file."""
        logging.info("Loading bundle from %s", filepath)  # Log before file read
        try:
            with open(filepath, encoding="utf-8") as bundle_file:  # Open with UTF-8 for JSON
                bundle = json.load(bundle_file)  # Parse JSON into Python dict
        except (json.JSONDecodeError, OSError) as error:  # Handle corrupt JSON or file access errors
            print(f"  X Error reading bundle: {error}")  # User feedback
            logging.error("Failed to load bundle %s: %s", filepath, error)  # Log error details
            return None  # Signal invalid bundle

        logging.debug("Bundle loaded, validating structure")  # Log validation start
        if not self._validate_bundle_structure(bundle):  # Check required keys exist
            return None  # Signal failed validation
        return bundle  # type: ignore[no-any-return] # Return validated bundle

    def _validate_bundle_structure(self, bundle: dict) -> bool:  # type: ignore[type-arg]
        """Check that the bundle has required metadata and type keys."""
        if "metadata" not in bundle:  # Metadata section is mandatory
            print("  X Invalid bundle: missing 'metadata' section.")  # User feedback
            return False  # Fail validation

        required_keys = {ct["key"] for ct in self.CONFIG_TYPES}  # Build set of expected type keys
        missing = required_keys - set(bundle.keys())  # Find any missing config type sections
        if missing:  # Some config types are not in the bundle
            print(f"  X Invalid bundle: missing config types: {', '.join(sorted(missing))}")  # Show which
            return False  # Fail validation

        source_org = bundle["metadata"].get("source_org_id", "unknown")  # Check source org identity
        if source_org == self.org_id:  # Source matches destination -- likely a mistake
            print(f"  ! WARNING: Source org ({source_org[:8]}...) matches destination org.")  # Warn user
            print("  This will likely result in all objects being detected as conflicts.")  # Explain

        return True  # Bundle structure is valid

    def _display_bundle_preview(self, bundle: dict) -> None:  # type: ignore[type-arg]
        """Show a preview of what the bundle contains before importing."""
        metadata = bundle["metadata"]  # Extract metadata section for display
        print(f"\n  Bundle from: {metadata.get('source_org_name', 'Unknown')}")  # Source org name
        print(f"  Exported at: {metadata.get('export_timestamp', 'Unknown')}")  # When it was exported
        print(f"  Source org:  {metadata.get('source_org_id', 'Unknown')[:8]}...")  # Truncated org ID
        counts = metadata.get("object_counts", {})  # Per-type object counts
        total = sum(counts.values())  # Total across all types
        print(f"  Total objects: {total}")  # Grand total for user awareness

    def _prompt_dry_run(self) -> bool:
        """Ask if the user wants a dry-run (preview only)."""
        choice = self.safe_input_fn(  # EOF-safe input for SSH/container contexts
            "\n  Run as dry-run (preview only)? [Y/n]: ",
            default_value="Y",  # Default to dry-run for safety
            context="import_dry_run",
        )
        return choice.upper() != "N"  # Anything except explicit 'N' means dry-run

    def _confirm_import(self) -> bool:
        """Require typed 'IMPORT' confirmation for actual import."""
        print("\n  WARNING: This will create configuration objects in the destination org.")  # Safety warning
        print("  This operation cannot be automatically undone.")  # Emphasize irreversibility
        confirmation = self.safe_input_fn(  # EOF-safe typed confirmation
            "  Type 'IMPORT' to proceed: ",
            context="import_confirmation",
        )
        if confirmation != "IMPORT":  # Exact match required -- no partial or lowercase
            print("  Import cancelled.")  # User feedback
            return False  # Signal cancellation
        return True  # User explicitly confirmed

    # ------------------------------------------------------------------
    # Conflict detection
    # ------------------------------------------------------------------

    def _fetch_existing_objects(self) -> None:
        """Fetch current objects from destination org for conflict detection."""
        print("\n  Fetching existing config from destination org...")  # User feedback
        logging.info("Fetching existing objects from destination org for conflict detection")  # Log operation
        for config_type in self.CONFIG_TYPES:  # Iterate all 6 config types
            items = self._fetch_config_type(config_type)  # Reuse same fetch logic as export
            self._existing[config_type["key"]] = items  # Cache for conflict checks
        logging.debug("Cached %s total existing objects", sum(len(v) for v in self._existing.values()))  # Log count

    def _detect_conflicts(self, new_obj: dict, type_key: str) -> dict | None:  # type: ignore[type-arg]
        """Check for name match and IP/subnet overlap with existing objects."""
        existing_list = self._existing.get(type_key, [])  # Get cached objects for this type
        conflict = self._check_name_conflict(new_obj, existing_list)  # Check name collision first
        if conflict:  # Name match found -- return immediately
            return conflict

        config_entry = next((ct for ct in self.CONFIG_TYPES if ct["key"] == type_key), None)  # Find config metadata
        if config_entry and config_entry.get("conflict_check"):  # Only check subnets for types that need it
            return self._check_subnet_overlap(new_obj, existing_list, type_key)  # Check IP/subnet overlaps
        return None  # No conflicts detected

    def _check_name_conflict(self, new_obj: dict, existing_list: list) -> dict | None:  # type: ignore[type-arg]
        """Check if an object with the same name already exists (case-insensitive)."""
        new_name = (new_obj.get("name") or "").lower()  # Normalize to lowercase for comparison
        if not new_name:  # Skip unnamed objects (shouldn't happen but be defensive)
            return None
        for existing in existing_list:  # Check every existing object in destination
            existing_name = (existing.get("name") or "").lower()  # Normalize existing name
            if new_name == existing_name:  # Case-insensitive match found
                return {
                    "reason": "name_match",  # Conflict type for reporting
                    "detail": f"Object named '{existing.get('name')}' already exists",  # Human-readable
                    "existing_id": existing.get("id"),  # Preserve for ID remapping
                }
        return None  # No name conflict found

    def _check_subnet_overlap(self, new_obj: dict, existing_list: list, type_key: str) -> dict | None:  # type: ignore[type-arg]
        """Check for IP/subnet overlaps between new and existing objects."""
        if type_key == "networks":  # Networks use subnet field for CIDR
            return self._check_network_subnet_overlap(new_obj, existing_list)
        if type_key == "services":  # Services use addresses[] array
            return self._check_service_address_overlap(new_obj, existing_list)
        return None  # Other types don't have IP fields

    def _check_network_subnet_overlap(self, new_obj: dict, existing_list: list) -> dict | None:  # type: ignore[type-arg]
        """Check network subnet overlap using ipaddress module."""
        new_subnet = new_obj.get("subnet")  # Get the CIDR subnet string
        if not new_subnet:  # No subnet defined -- skip overlap check
            return None
        try:
            new_net = ipaddress.ip_network(new_subnet, strict=False)  # Parse CIDR, allow host bits
        except ValueError:  # Invalid CIDR format -- skip gracefully
            return None
        for existing in existing_list:  # Compare against each existing network
            existing_subnet = existing.get("subnet")  # Get existing network's CIDR
            if not existing_subnet:  # Skip existing networks without subnets
                continue
            try:
                existing_net = ipaddress.ip_network(existing_subnet, strict=False)  # Parse for comparison
                if new_net.overlaps(existing_net):  # Check if any IP addresses are shared
                    return {
                        "reason": "subnet_overlap",  # Conflict type for reporting
                        "detail": f"{new_subnet} overlaps with '{existing.get('name')}' ({existing_subnet})",
                    }
            except ValueError:  # Invalid existing CIDR -- skip and continue
                continue
        return None  # No subnet overlaps found

    def _check_service_address_overlap(self, new_obj: dict, existing_list: list) -> dict | None:  # type: ignore[type-arg]
        """Check service address overlap for objects with addresses[] field."""
        new_addrs = new_obj.get("addresses", [])  # Get list of IP/CIDR addresses
        if not new_addrs:  # No addresses to check -- skip
            return None
        for addr in new_addrs:  # Check each address in the new service
            overlap = self._check_single_address(addr, existing_list)  # Compare against all existing
            if overlap:  # First overlap found -- return immediately
                return overlap
        return None  # No address overlaps found

    def _check_single_address(self, addr: str, existing_list: list) -> dict | None:  # type: ignore[type-arg]
        """Check a single address against all existing service addresses."""
        try:
            new_net = ipaddress.ip_network(addr, strict=False)  # Parse address as network for overlap check
        except ValueError:  # Invalid address format -- skip
            return None
        for existing in existing_list:  # Compare against each existing service
            for ex_addr in existing.get("addresses", []):  # Check each address in existing service
                try:
                    ex_net = ipaddress.ip_network(ex_addr, strict=False)  # Parse existing address
                    if new_net.overlaps(ex_net):  # Check if any IP addresses overlap
                        return {
                            "reason": "address_overlap",  # Conflict type for reporting
                            "detail": f"{addr} overlaps with '{existing.get('name')}' ({ex_addr})",
                        }
                except ValueError:  # Invalid existing address -- skip and continue
                    continue
        return None  # No address overlap found

    # ------------------------------------------------------------------
    # ID remapping
    # ------------------------------------------------------------------

    def _build_remap_entry(self, source_id: str, dest_id: str) -> None:
        """Record a source-to-destination ID mapping."""
        self._remap_table[source_id] = dest_id  # Store mapping for cross-reference remapping
        logging.debug("ID remap: %s -> %s", source_id[:8], dest_id[:8])  # Log truncated IDs for tracing

    def _remap_object_references(self, obj: dict, type_key: str) -> dict:  # type: ignore[type-arg]
        """Remap foreign ID references in an object using the remap table."""
        if type_key == "vpns":  # VPNs reference network IDs
            self._remap_vpn_networks(obj)
        elif type_key == "gateway_templates":  # Gateway templates reference network/VPN IDs
            self._remap_gateway_template_refs(obj)
        elif type_key == "device_profiles":  # Device profiles reference gateway template IDs
            self._remap_device_profile_refs(obj)
        elif type_key == "service_policies":  # Service policies reference service IDs
            self._remap_service_policy_refs(obj)
        return obj  # Return object with remapped references

    def _remap_vpn_networks(self, obj: dict) -> None:  # type: ignore[type-arg]
        """Remap network IDs inside VPN network entries."""
        networks = obj.get("networks", {})  # VPN networks is a dict of name->config
        if not isinstance(networks, dict):  # Guard against unexpected data shapes
            return
        remapped: dict[str, dict] = {}  # type: ignore[type-arg] # Build new dict with remapped IDs
        for net_name, net_config in networks.items():  # Iterate each network entry
            if isinstance(net_config, dict) and "id" in net_config:  # Check if entry has an ID to remap
                old_id = net_config["id"]  # Capture source org's network ID
                net_config["id"] = self._remap_table.get(old_id, old_id)  # Swap to dest ID or keep original
            remapped[net_name] = net_config  # Preserve the entry in remapped dict
        obj["networks"] = remapped  # Replace with remapped version

    def _remap_gateway_template_refs(self, obj: dict) -> None:  # type: ignore[type-arg]
        """Remap network and VPN IDs in gateway template config."""
        networks = obj.get("networks", {})  # Gateway template networks section
        if isinstance(networks, dict):  # Verify expected dict structure
            for _net_name, net_config in networks.items():  # Iterate each network reference
                if isinstance(net_config, dict) and "id" in net_config:  # Has remappable ID
                    old_id = net_config["id"]  # Capture source org's ID
                    net_config["id"] = self._remap_table.get(old_id, old_id)  # Swap to dest ID

    def _remap_device_profile_refs(self, obj: dict) -> None:  # type: ignore[type-arg]
        """Remap gateway_template_id in device profiles."""
        old_id = obj.get("gateway_template_id")  # Check if profile references a gateway template
        if old_id and old_id in self._remap_table:  # Only remap if we have a mapping
            obj["gateway_template_id"] = self._remap_table[old_id]  # Swap to destination template ID

    def _remap_service_policy_refs(self, obj: dict) -> None:  # type: ignore[type-arg]
        """Remap service IDs in service policy rules."""
        services = obj.get("services", [])  # Service policies contain a list of service refs
        if not isinstance(services, list):  # Guard against unexpected data shapes
            return
        for service_entry in services:  # Iterate each service reference in the policy
            if isinstance(service_entry, dict) and "id" in service_entry:  # Has remappable ID
                old_id = service_entry["id"]  # Capture source org's service ID
                service_entry["id"] = self._remap_table.get(old_id, old_id)  # Swap to dest service ID

    # ------------------------------------------------------------------
    # Import execution
    # ------------------------------------------------------------------

    def _strip_source_fields(self, obj: dict) -> dict:  # type: ignore[type-arg]
        """Return a copy of obj with source-org-specific fields removed."""
        return {key: value for key, value in obj.items() if key not in self.STRIP_FIELDS}  # Filter out id, org_id, etc.

    def _execute_import(self, bundle: dict, dry_run: bool) -> list:  # type: ignore[type-arg]
        """Import objects in dependency order, skipping conflicts."""
        results: list = []  # type: ignore[type-arg] # Accumulates import results for final report
        sorted_types = sorted(self.CONFIG_TYPES, key=lambda ct: ct["import_order"])  # Dependency order
        action_label = "[DRY RUN] " if dry_run else ""  # Prefix for user output in dry-run mode
        print(f"\n  {action_label}Importing configuration objects...")  # User feedback

        for config_type in sorted_types:  # Process each type in dependency order
            objects = bundle.get(config_type["key"], [])  # Get objects of this type from bundle
            if not objects:  # Skip empty types
                continue
            self._import_type_batch(config_type, objects, dry_run, results)  # Import the batch
        return results  # Return all results for report

    def _import_type_batch(  # type: ignore[type-arg]
        self,
        config_type: dict,
        objects: list,
        dry_run: bool,
        results: list,
    ) -> None:
        """Import a batch of objects for a single config type."""
        display = config_type["display_name"]  # Human-readable type name for output
        label = "[DRY RUN] " if dry_run else ""  # Prefix for dry-run output
        print(f"\n    {label}{display} ({len(objects)} objects):")  # User feedback with count
        logging.info("Importing %s %s objects (dry_run=%s)", len(objects), display, dry_run)  # Log batch start

        for obj in objects:  # Process each object in the batch
            self._process_import_object(config_type, obj, dry_run, results)  # Delegate per-object logic

    def _process_import_object(  # type: ignore[type-arg]
        self,
        config_type: dict,
        obj: dict,
        dry_run: bool,
        results: list,
    ) -> None:
        """Process a single object: conflict check, remap, create or skip."""
        obj_name = obj.get("name", "unnamed")  # Extract object name for logging and reporting
        source_id = obj.get("id", "")  # Capture source org ID for remapping
        type_key = config_type["key"]  # Bundle key for this config type
        label = "[DRY RUN] " if dry_run else ""  # Prefix for output

        conflict = self._detect_conflicts(obj, type_key)  # Check for name/subnet conflicts
        if conflict:  # Conflict found -- skip and record
            self._record_conflict(type_key, obj_name, source_id, conflict, results)
            return

        cleaned = self._strip_source_fields(obj)  # Remove source-org-specific fields
        cleaned = self._remap_object_references(cleaned, type_key)  # Remap cross-references to dest IDs

        if dry_run:  # Preview mode -- don't make API calls
            print(f"      {label}Would import: {obj_name}")  # Show what would happen
            results.append({"type": type_key, "name": obj_name, "status": "would_import"})  # Record for report
            return

        self._create_and_record(config_type, cleaned, obj_name, source_id, results)  # Create via API

    def _record_conflict(  # type: ignore[type-arg]
        self,
        type_key: str,
        name: str,
        source_id: str,
        conflict: dict,
        results: list,
    ) -> None:
        """Record a skipped object due to conflict and update remap table."""
        print(f"      SKIP: {name} - {conflict['detail']}")  # User feedback showing skip reason
        results.append({"type": type_key, "name": name, "status": "skipped", "reason": conflict["detail"]})  # Record
        existing_id = conflict.get("existing_id")  # Get destination org's matching object ID
        if existing_id and source_id:  # Both IDs available -- record mapping for cross-references
            self._build_remap_entry(source_id, existing_id)

    def _create_and_record(  # type: ignore[type-arg]
        self,
        config_type: dict,
        cleaned: dict,
        name: str,
        source_id: str,
        results: list,
    ) -> None:
        """Create a single object via the API and record the result."""
        type_key = config_type["key"]  # Bundle key for logging
        logging.info("Creating %s '%s' in destination org", type_key, name)  # Log before API call
        try:
            create_fn = self._resolve_api_fn(config_type["create_fn"])  # Resolve create endpoint
            response = create_fn(self.session, self.org_id, body=cleaned)  # Call Mist API to create
            new_id = self._extract_created_id(response)  # Extract new object ID from response
            if source_id and new_id:  # Record mapping for downstream cross-references
                self._build_remap_entry(source_id, new_id)
            print(f"      OK: {name}")  # User feedback showing success
            logging.debug("Created %s '%s' with ID %s", type_key, name, new_id[:8] if new_id else "n/a")  # Log result
            results.append({"type": type_key, "name": name, "status": "imported"})  # Record success
        except Exception as error:  # Catch API errors without stopping the entire import
            print(f"      FAIL: {name} - {error}")  # User feedback showing failure
            logging.error("Failed to create %s '%s': %s", type_key, name, error)  # Log error with context
            results.append({"type": type_key, "name": name, "status": "failed", "reason": str(error)})  # Record failure

    def _extract_created_id(self, response) -> str:  # type: ignore[no-untyped-def]
        """Extract the new object ID from a create API response."""
        if hasattr(response, "data") and isinstance(response.data, dict):  # Check response has data dict
            return response.data.get("id", "")  # type: ignore[no-any-return] # Return the new ID
        return ""  # Fallback when response format is unexpected

    # ------------------------------------------------------------------
    # Import report
    # ------------------------------------------------------------------

    def _display_import_report(self, results: list) -> None:  # type: ignore[type-arg]
        """Print a summary report of the import operation."""
        imported = [r for r in results if r["status"] == "imported"]  # Filter successfully imported
        skipped = [r for r in results if r["status"] == "skipped"]  # Filter conflict-skipped
        failed = [r for r in results if r["status"] == "failed"]  # Filter API failures
        would_import = [r for r in results if r["status"] == "would_import"]  # Filter dry-run previews

        print("\n  " + "=" * 55)  # Report header separator
        print("  IMPORT REPORT")  # Report title
        print("  " + "=" * 55)  # Report header separator

        if would_import:  # Show dry-run preview section if applicable
            self._print_report_section("WOULD IMPORT (dry-run)", would_import)
        if imported:  # Show successfully imported section
            self._print_report_section("IMPORTED", imported)
        if skipped:  # Show skipped-due-to-conflicts section
            self._print_report_section("SKIPPED (conflicts)", skipped)
        if failed:  # Show failed-to-import section
            self._print_report_section("FAILED", failed)

        self._print_report_totals(imported, skipped, failed, would_import)  # Show grand totals

    def _print_report_section(self, title: str, items: list) -> None:  # type: ignore[type-arg]
        """Print a single section of the import report."""
        print(f"\n  {title} ({len(items)}):")  # Section header with count
        for item in items:  # Iterate each result in this section
            reason = item.get("reason", "")  # Get conflict/error reason if present
            suffix = f" -- {reason}" if reason else ""  # Append reason as suffix
            print(f"    {item['type']:<20} {item['name']:<30}{suffix}")  # Aligned columns

    def _print_report_totals(self, imported: list, skipped: list, failed: list, would_import: list) -> None:  # type: ignore[type-arg]
        """Print the totals row of the import report."""
        print("\n  " + "-" * 55)  # Separator before totals
        total = len(imported) + len(skipped) + len(failed) + len(would_import)  # Grand total
        print(f"  Total: {total} objects processed")  # Total line
        if would_import:  # Show dry-run count
            print(f"    Would import: {len(would_import)}")
        if imported:  # Show imported count
            print(f"    Imported:     {len(imported)}")
        if skipped:  # Show skipped count
            print(f"    Skipped:      {len(skipped)}")
        if failed:  # Show failed count
            print(f"    Failed:       {len(failed)}")


# ============================================================================
# WAN PROBE CONFIGURATION MANAGER CLASS
# ============================================================================
class WANProbeConfigManager:
    """
    Manages WAN interface ICMP probe configuration for gateway templates.

    Menu #166: Configure WAN probe override settings (probe IPs and profile)
    for all WAN interfaces across selected gateway templates.

    Default Configuration:
        - probe IPs: ["192.151.29.254", "18.154.184.32"]
        - probe_profile: "lte"

    This operation updates the wan_probe_override section for all interfaces
    where usage == "wan" in the template's port_config.
    """

    # Default probe configuration - loaded from environment variables
    # MIST_WAN_PROBE_IPS: Comma-separated list of probe IPs (e.g., "192.151.29.254,18.154.184.32")
    # MIST_WAN_PROBE_PROFILE: Probe profile name (e.g., "lte")
    DEFAULT_PROBE_IPS = [
        ip.strip() for ip in os.getenv("MIST_WAN_PROBE_IPS", "192.151.29.254,18.154.184.32").split(",") if ip.strip()
    ]
    DEFAULT_PROBE_PROFILE = os.getenv("MIST_WAN_PROBE_PROFILE", "lte")

    def __init__(self):  # type: ignore[no-untyped-def]
        """Initialize the WAN Probe Configuration Manager."""
        self.org_id = None
        self.templates = []
        self.sites = []
        self.template_site_counts: dict[str, int] = {}
        self.probe_ips = self.DEFAULT_PROBE_IPS.copy()
        self.probe_profile = self.DEFAULT_PROBE_PROFILE

    @classmethod
    def configure(cls, dry_run: bool = False) -> None:
        """
        Menu #166: Configure WAN Probe Override on Gateway Templates (DESTRUCTIVE)

        Updates wan_probe_override settings for all WAN interfaces in selected
        gateway templates. Replaces existing probe IPs with configured values.

        Args:
            dry_run: If True, show what would change without making modifications
        """
        manager = cls()
        manager._execute(dry_run)

    def _execute(self, dry_run: bool) -> None:
        """Main execution flow for WAN probe configuration."""
        self._display_header(dry_run)

        if not self._initialize():
            return

        if not self._load_data():
            return

        templates_to_modify = self._select_templates()
        if not templates_to_modify:
            return

        templates_with_changes = self._analyze_templates(templates_to_modify)
        if not templates_with_changes:
            print("\n  No WAN interfaces found in selected templates.")
            print("  No changes needed.")
            logging.info("Menu #166: No WAN interfaces found in selected templates")
            return

        self._show_preview(templates_with_changes, dry_run)

        if not dry_run:
            if not self._confirm_operation(len(templates_with_changes)):
                return

        results = self._apply_changes(templates_with_changes, dry_run)
        self._generate_report(results, dry_run)

    def _display_header(self, dry_run: bool) -> None:
        """Display operation header with configuration details."""
        print("\n  DESTRUCTIVE: Configure WAN Interface ICMP Probe Settings")
        print("=" * 70)
        if dry_run:
            print("  >> DRY-RUN MODE: No changes will be made to templates")
            print("  >> This will show what WOULD be changed without modifying anything")
        else:
            print("  !? WARNING: This operation modifies gateway templates")
            print("  !? All sites using affected templates will inherit the change")
        print("=" * 70)
        print("\n  Probe Configuration:")
        print(f"    Probe IPs: {self.probe_ips}")
        print(f"    Probe Profile: {self.probe_profile}")
        print("=" * 70)
        logging.warning("Menu #166 DESTRUCTIVE: Configure WAN Probe Override operation started")

    def _initialize(self) -> bool:
        """Initialize org_id. Returns True on success."""
        self.org_id = ConfigUtils.get_cached_or_prompted_org_id()
        if not self.org_id:
            print(" Failed to get organization ID.")
            logging.error("Menu #166: Could not obtain org_id")
            return False
        return True

    def _load_data(self) -> bool:
        """Load gateway templates and site data. Returns True on success."""
        print("\n  Loading gateway template data...")
        CacheUtils.check_and_generate_csv("OrgGatewayTemplates.csv", GatewayExportUtils.templates)
        CacheUtils.check_and_generate_csv("SiteList.csv", OrgSiteExporter.sites)

        templates_path = FilePathUtils.get_csv_path("OrgGatewayTemplates.csv")
        with open(templates_path, encoding="utf-8") as file_handle:
            self.templates = list(csv.DictReader(file_handle))

        if not self.templates:
            print(" No gateway templates found.")
            logging.warning("Menu #166: No gateway templates available")
            return False

        sites_path = FilePathUtils.get_csv_path("SiteList.csv")
        with open(sites_path, encoding="utf-8") as file_handle:
            self.sites = list(csv.DictReader(file_handle))

        # Build template site counts (excluding sites matching MIST_SITE_EXCLUDE_PREFIX)
        for site in self.sites:
            if MIST_SITE_EXCLUDE_PREFIX and site.get("name", "").startswith(MIST_SITE_EXCLUDE_PREFIX):
                continue
            template_id = site.get("gatewaytemplate_id", "").strip()
            if template_id:
                self.template_site_counts[template_id] = self.template_site_counts.get(template_id, 0) + 1

        logging.info(f"Loaded {len(self.templates)} gateway templates and {len(self.sites)} sites")
        return True

    def _select_templates(self) -> list[dict[str, Any]]:
        """Display templates and get user selection. Returns selected templates."""
        templates_sorted = sorted(self.templates, key=lambda t: t.get("name", "").lower())

        print(f"\n  Available Gateway Templates ({len(templates_sorted)}):")
        template_list = []
        for idx, template in enumerate(templates_sorted, start=1):
            template_id = template.get("id", "")
            template_name = template.get("name", "Unnamed Template")
            site_count = self.template_site_counts.get(template_id, 0)
            template_list.append({"id": template_id, "name": template_name, "site_count": site_count})
            print(f"   [{idx}] {template_name} ({site_count} sites)")

        print("\n  Template Selection:")
        print("   Enter template numbers (comma-separated, e.g., 1,3,5)")
        print("   Or 'all' to modify all templates")
        print("   Or 'cancel' to abort")

        selection = (
            InputUtils.safe_input(
                "\n  Selection: ",
                context="wan_probe_template_selection",
            )
            .strip()
            .lower()
        )

        if selection == "cancel":
            print(" Operation cancelled.")
            logging.info("Menu #166 cancelled by user at template selection")
            return []

        if selection == "all":
            return template_list

        try:
            indices = [int(idx.strip()) - 1 for idx in selection.split(",")]
            selected = [template_list[idx] for idx in indices if 0 <= idx < len(template_list)]
            if not selected:
                print(" No valid templates selected.")
                return []
            return selected
        except (ValueError, IndexError) as error:
            print(f" Invalid selection: {error}")
            logging.error(f"Menu #166: Invalid template selection: {error}")
            return []

    def _analyze_templates(self, templates_to_modify: list[dict[str, Any]]) -> list[dict[str, Any]]:
        """Fetch and analyze templates for WAN interfaces. Returns templates with changes."""
        print(f"\n  Analyzing {len(templates_to_modify)} templates for WAN interfaces...")
        templates_with_changes = []

        def fetch_and_analyze(template_info: dict[str, Any]) -> dict[str, Any] | None:
            """Worker function to fetch and analyze a single template."""
            template_id = template_info["id"]
            template_name = template_info["name"]

            try:
                logging.debug(f"Fetching template configuration for {template_name}")
                response = mistapi.api.v1.orgs.gatewaytemplates.getOrgGatewayTemplate(
                    apisession, self.org_id, template_id
                )
                config = response.data if hasattr(response, "data") else {}

                if not isinstance(config, dict):
                    logging.warning(f"Template {template_name} returned invalid structure")
                    return None

                port_config = config.get("port_config", {})
                if not isinstance(port_config, dict):
                    logging.debug(f"Template {template_name} has no port_config")
                    return None

                # Find all WAN interfaces
                wan_interfaces = []
                for port_name, port_settings in port_config.items():
                    if isinstance(port_settings, dict) and port_settings.get("usage") == "wan":
                        current_probe = port_settings.get("wan_probe_override", {})
                        current_ips = current_probe.get("ips", []) if isinstance(current_probe, dict) else []
                        current_profile = (
                            current_probe.get("probe_profile", "") if isinstance(current_probe, dict) else ""
                        )

                        wan_interfaces.append(
                            {"port_name": port_name, "current_ips": current_ips, "current_profile": current_profile}
                        )

                if wan_interfaces:
                    return {
                        "id": template_id,
                        "name": template_name,
                        "site_count": template_info["site_count"],
                        "config": config,
                        "wan_interfaces": wan_interfaces,
                    }
                return None

            except Exception as error:
                logging.error(f"Error analyzing template {template_name}: {error}")
                logging.error(traceback.format_exc())
                print(f"\n  !? Error analyzing template '{template_name}': {error}")
                return None

        # Parallel fetch with ThreadPoolExecutor
        max_workers = min(10, len(templates_to_modify))
        logging.info(f"Fetching {len(templates_to_modify)} templates in parallel (max {max_workers} workers)")

        with ThreadPoolExecutor(max_workers=max_workers) as executor:
            import concurrent.futures

            future_map = {executor.submit(fetch_and_analyze, t): t for t in templates_to_modify}

            for future in tqdm(  # type: ignore[no-untyped-call]
                concurrent.futures.as_completed(future_map),
                total=len(templates_to_modify),
                desc="Analyzing templates",
                unit="template",
            ):
                result = future.result()
                if result:
                    templates_with_changes.append(result)

        return templates_with_changes

    def _show_preview(self, templates_with_changes: list[dict[str, Any]], dry_run: bool) -> None:
        """Display preview of changes to be made."""
        total_interfaces = sum(len(t["wan_interfaces"]) for t in templates_with_changes)
        total_sites = sum(t["site_count"] for t in templates_with_changes)

        print("\n  Preview of Changes:")
        print(f"  {len(templates_with_changes)} templates with {total_interfaces} WAN interfaces")
        print(f"  Affecting {total_sites} sites")

        for template in templates_with_changes:
            print(f"\n   Template: {template['name']} ({template['site_count']} sites)")
            for wan_if in template["wan_interfaces"]:
                port = wan_if["port_name"]
                current_ips = wan_if["current_ips"] or ["(none)"]
                current_profile = wan_if["current_profile"] or "(none)"
                print(f"     {port}:")
                print(f"       Current: ips={current_ips}, profile={current_profile}")
                print(f"       New:     ips={self.probe_ips}, profile={self.probe_profile}")

    def _confirm_operation(self, template_count: int) -> bool:
        """Prompt for confirmation. Returns True if confirmed."""
        print(f"\n  {'=' * 70}")
        print(f"  !? CRITICAL: This will modify {template_count} gateway templates")
        print("  !? Type 'APPLY' (all caps) to proceed or anything else to cancel")
        print(f"  {'=' * 70}")

        confirmation = InputUtils.safe_input(
            "\n  Confirmation: ",
            context="wan_probe_apply_confirmation",
        ).strip()
        if confirmation != "APPLY":
            print(" Operation cancelled.")
            logging.info("Menu #166 cancelled by user at final confirmation")
            return False
        return True

    def _apply_changes(self, templates_with_changes: list[dict[str, Any]], dry_run: bool) -> list[dict[str, Any]]:
        """Apply probe configuration changes to templates. Returns results."""
        print("\n  Applying WAN probe configuration...")
        results = []

        for template in tqdm(templates_with_changes, desc="Updating templates", unit="template"):  # type: ignore[no-untyped-call]
            result = self._update_single_template(template, dry_run)
            results.append(result)

        return results

    def _update_single_template(self, template: dict[str, Any], dry_run: bool) -> dict[str, Any]:
        """Update a single template's WAN probe configuration."""
        template_id = template["id"]
        template_name = template["name"]
        config = template["config"]

        result = {
            "template_name": template_name,
            "template_id": template_id,
            "site_count": template["site_count"],
            "interfaces_updated": [],
            "status": "",
            "error": "",
        }

        try:
            port_config = config.get("port_config", {})
            interfaces_modified = []

            for wan_if in template["wan_interfaces"]:
                port_name = wan_if["port_name"]
                if port_name in port_config:
                    # Set wan_probe_override
                    port_config[port_name]["wan_probe_override"] = {
                        "ips": self.probe_ips.copy(),
                        "probe_profile": self.probe_profile,
                    }
                    interfaces_modified.append(port_name)
                    logging.debug(f"Template {template_name}: Updated {port_name} probe config")

            if interfaces_modified:
                config["port_config"] = port_config
                result["interfaces_updated"] = interfaces_modified

                if dry_run:
                    result["status"] = "DRY-RUN"
                    logging.info(f"DRY-RUN: Would update template {template_name} interfaces: {interfaces_modified}")
                else:
                    logging.debug(f"Updating template {template_name} via API")
                    update_resp = mistapi.api.v1.orgs.gatewaytemplates.updateOrgGatewayTemplate(
                        apisession, self.org_id, template_id, body=config
                    )

                    if update_resp.status_code == 200:
                        result["status"] = "SUCCESS"
                        logging.info(f"Successfully updated template {template_name}")
                    else:
                        result["status"] = "FAILED"
                        result["error"] = f"API returned status {update_resp.status_code}"
                        logging.error(f"Failed to update template {template_name}: status {update_resp.status_code}")
            else:
                result["status"] = "SKIPPED"
                result["error"] = "No WAN interfaces found in port_config"

        except Exception as error:
            result["status"] = "ERROR"
            result["error"] = str(error)
            logging.error(f"Error updating template {template_name}: {error}")
            logging.error(traceback.format_exc())

        return result

    def _generate_report(self, results: list[dict[str, Any]], dry_run: bool) -> None:
        """Generate and display final report."""
        # Prepare report data
        report_data = []
        for result in results:
            report_data.append(
                {
                    "template_name": result["template_name"],
                    "template_id": result["template_id"],
                    "site_count": result["site_count"],
                    "interfaces_updated": (
                        ", ".join(result["interfaces_updated"]) if result["interfaces_updated"] else ""
                    ),
                    "interface_count": len(result["interfaces_updated"]),
                    "status": result["status"],
                    "error": result["error"],
                    "new_probe_ips": ", ".join(self.probe_ips),
                    "new_probe_profile": self.probe_profile,
                }
            )

        output_file = "GatewayTemplate_WAN_Probe_Config_Audit.csv"
        DataExporter.save_data_to_output(report_data, output_file)  # type: ignore[no-untyped-call]

        # Calculate summary
        total_interfaces = sum(len(r["interfaces_updated"]) for r in results)
        total_sites = sum(r["site_count"] for r in results if r["status"] in ["SUCCESS", "DRY-RUN"])

        if dry_run:
            dry_run_count = sum(1 for r in results if r["status"] == "DRY-RUN")
            print("\n  WAN Probe Configuration DRY-RUN Complete!")
            print("=" * 70)
            print("  >> DRY-RUN MODE: No actual changes were made")
            print(f"  Templates Analyzed: {len(results)}")
            print(f"  Would Update: {dry_run_count} templates")
            print(f"  WAN Interfaces: {total_interfaces}")
            print(f"  Sites Affected: {total_sites}")
            print("\n  >> To apply changes, run without --dry-run flag")
        else:
            success_count = sum(1 for r in results if r["status"] == "SUCCESS")
            failure_count = len(results) - success_count

            print("\n  WAN Probe Configuration Complete!")
            print("=" * 70)
            print(f"  Templates Updated: {success_count}")
            print(f"  Templates Failed: {failure_count}")
            print(f"  WAN Interfaces Configured: {total_interfaces}")
            print(f"  Sites Affected: {total_sites}")

            if success_count > 0:
                print("\n  Configuration Applied:")
                print(f"    Probe IPs: {self.probe_ips}")
                print(f"    Probe Profile: {self.probe_profile}")

            if failure_count > 0:
                print(f"\n  !? {failure_count} templates failed - check audit report")

        print(f"\n  Report saved to: {output_file}")
        print("=" * 70)

        logging.warning(
            f"Menu #166 DESTRUCTIVE operation complete: {sum(1 for r in results if r['status'] == 'SUCCESS')} templates updated"  # noqa: E501
        )


# ============================================================================
# WAN PROBE DEVICE OVERRIDE MANAGER CLASS
# ============================================================================
class _LegacyWANProbeDeviceOverrideManager:
    """
    Manages WAN probe configuration for device-level port overrides.

    Menu #167: Configure WAN probe override settings on gateway devices that
    have device-level port overrides. This complements Menu #166 (template-level)
    by targeting ONLY ports that have been overridden from their template.

    Workflow:
        1. User selects a gateway template
        2. Find all sites using that template
        3. Find all gateway devices in those sites
        4. Identify devices with port-level WAN overrides
        5. Apply ICMP probe configuration to ONLY overridden WAN ports

    Default Configuration:
        - probe IPs: ["192.151.29.254", "18.154.184.32"] (override via MIST_WAN_PROBE_IPS)
        - probe_profile: "lte" (override via MIST_WAN_PROBE_PROFILE)
    """

    # Default probe configuration - loaded from environment variables (same as Menu 113)
    # MIST_WAN_PROBE_IPS: Comma-separated list of probe IPs (e.g., "192.151.29.254,18.154.184.32")
    # MIST_WAN_PROBE_PROFILE: Probe profile name (e.g., "lte")
    DEFAULT_PROBE_IPS = [
        ip.strip() for ip in os.getenv("MIST_WAN_PROBE_IPS", "192.151.29.254,18.154.184.32").split(",") if ip.strip()
    ]
    DEFAULT_PROBE_PROFILE = os.getenv("MIST_WAN_PROBE_PROFILE", "lte")

    def __init__(self):  # type: ignore[no-untyped-def]
        """Initialize the WAN Probe Device Override Manager."""
        self.org_id: str | None = None
        self.templates: list[dict[str, Any]] = []
        self.sites: list[dict[str, Any]] = []
        self.probe_ips = self.DEFAULT_PROBE_IPS.copy()
        self.probe_profile = self.DEFAULT_PROBE_PROFILE
        self.selected_template: dict[str, Any] | None = None
        self.template_sites: list[dict[str, Any]] = []

    @classmethod
    def configure(cls, dry_run: bool = False) -> None:
        """
        Menu #167: Configure WAN Probe Override on Device Port Overrides (DESTRUCTIVE)

        Updates wan_probe_override settings for WAN ports that have device-level
        overrides from their gateway template.

        Args:
            dry_run: If True, show what would change without making modifications
        """
        manager = cls()
        manager._execute(dry_run)

    def _execute(self, dry_run: bool) -> None:
        """Main execution flow for device-level WAN probe configuration."""
        self._display_header(dry_run)

        if not self._initialize():
            return

        if not self._load_data():
            return

        if not self._select_template():
            return

        if not self._find_template_sites():
            return

        devices_with_overrides = self._find_devices_with_overrides()
        if not devices_with_overrides:
            return

        self._show_preview(devices_with_overrides, dry_run)

        if not dry_run:
            if not self._confirm_operation(len(devices_with_overrides)):
                return

        results = self._apply_changes(devices_with_overrides, dry_run)
        self._generate_report(results, dry_run)

    def _display_header(self, dry_run: bool) -> None:
        """Display operation header with configuration details."""
        print("\n  DESTRUCTIVE: Configure WAN Probe on Device Port Overrides")
        print("=" * 70)
        if dry_run:
            print("  >> DRY-RUN MODE: No changes will be made to devices")
            print("  >> This will show what WOULD be changed without modifying anything")
        else:
            print("  !? WARNING: This operation modifies gateway device configurations")
            print("  !? Only device-level overridden WAN ports will be modified")
        print("=" * 70)
        print("\n  Probe Configuration:")
        print(f"    Probe IPs: {self.probe_ips}")
        print(f"    Probe Profile: {self.probe_profile}")
        print("=" * 70)
        logging.warning("Menu #167 DESTRUCTIVE: Configure WAN Probe on Device Port Overrides started")

    def _initialize(self) -> bool:
        """Initialize org_id. Returns True on success."""
        self.org_id = ConfigUtils.get_cached_or_prompted_org_id()
        if not self.org_id:
            print(" Failed to get organization ID.")
            logging.error("Menu #167: Could not obtain org_id")
            return False
        return True

    def _load_data(self) -> bool:
        """Load gateway templates and site data. Returns True on success."""
        print("\n  Loading gateway template and site data...")
        CacheUtils.check_and_generate_csv("OrgGatewayTemplates.csv", GatewayExportUtils.templates)
        CacheUtils.check_and_generate_csv("SiteList.csv", OrgSiteExporter.sites)

        templates_path = FilePathUtils.get_csv_path("OrgGatewayTemplates.csv")
        with open(templates_path, encoding="utf-8") as file_handle:
            self.templates = list(csv.DictReader(file_handle))

        if not self.templates:
            print(" No gateway templates found.")
            logging.warning("Menu #167: No gateway templates available")
            return False

        sites_path = FilePathUtils.get_csv_path("SiteList.csv")
        with open(sites_path, encoding="utf-8") as file_handle:
            self.sites = list(csv.DictReader(file_handle))

        logging.info(f"Loaded {len(self.templates)} gateway templates and {len(self.sites)} sites")
        return True

    def _select_template(self) -> bool:
        """Display templates and get user selection. Returns True if selected."""
        templates_sorted = sorted(self.templates, key=lambda t: t.get("name", "").lower())

        # Build site counts per template (excluding sites matching MIST_SITE_EXCLUDE_PREFIX)
        template_site_counts: dict[str, int] = {}
        for site in self.sites:
            if MIST_SITE_EXCLUDE_PREFIX and site.get("name", "").startswith(MIST_SITE_EXCLUDE_PREFIX):
                continue
            template_id = site.get("gatewaytemplate_id", "").strip()
            if template_id:
                template_site_counts[template_id] = template_site_counts.get(template_id, 0) + 1

        print(f"\n  Available Gateway Templates ({len(templates_sorted)}):")
        template_list = []
        for idx, template in enumerate(templates_sorted, start=1):
            template_id = template.get("id", "")
            template_name = template.get("name", "Unnamed Template")
            site_count = template_site_counts.get(template_id, 0)
            template_list.append({"id": template_id, "name": template_name, "site_count": site_count})
            print(f"   [{idx}] {template_name} ({site_count} sites)")

        print("\n  Template Selection:")
        print("   Enter a template number to select")
        print("   Or 'cancel' to abort")

        selection = (
            InputUtils.safe_input(
                "\n  Selection: ",
                context="wan_probe_device_template_selection",
            )
            .strip()
            .lower()
        )

        if selection == "cancel":
            print(" Operation cancelled.")
            logging.info("Menu #167 cancelled by user at template selection")
            return False

        try:
            idx = int(selection) - 1
            if 0 <= idx < len(template_list):  # nosec B101
                self.selected_template = template_list[idx]
                assert self.selected_template is not None  # Type narrowing for Pylance  # nosec B101
                template_name = self.selected_template["name"]
                print(f"\n  Selected template: {template_name}")
                logging.info(f"Menu #167: Selected template {template_name}")
                return True
            else:
                print(" Invalid selection.")
                return False
        except ValueError:
            print(f" Invalid selection: {selection}")
            logging.error(f"Menu #167: Invalid template selection: {selection}")
            return False

    def _find_template_sites(self) -> bool:  # nosec B101
        """Find all sites using the selected template. Returns True if found."""
        assert self.selected_template is not None, "Template must be selected before finding sites"  # nosec B101
        template_id = self.selected_template["id"]
        template_name = self.selected_template["name"]

        self.template_sites = []
        for site in self.sites:
            if MIST_SITE_EXCLUDE_PREFIX and site.get("name", "").startswith(MIST_SITE_EXCLUDE_PREFIX):
                continue
            if site.get("gatewaytemplate_id", "").strip() == template_id:
                self.template_sites.append(
                    {"site_id": site.get("id", ""), "site_name": site.get("name", "Unknown Site")}
                )

        if not self.template_sites:
            print(f"\n  No sites found using template '{template_name}'.")
            logging.warning(f"Menu #167: No sites using template {template_name}")
            return False

        print(f"\n  Found {len(self.template_sites)} sites using template '{template_name}'")
        logging.info(f"Found {len(self.template_sites)} sites using template {template_name}")
        return True

    def _find_devices_with_overrides(self) -> list[dict[str, Any]]:  # noqa: C901, PLR0912
        """Find gateway devices with WAN port overrides. Returns list of devices."""
        print(f"\n  Scanning {len(self.template_sites)} sites for gateway devices...")

        # First pass: Find all gateway devices in template sites
        all_gateways = []
        for site_info in tqdm(self.template_sites, desc="Scanning sites", unit="site"):  # type: ignore[no-untyped-call]
            if ConfigUtils.check_stop_signal():
                break
            site_id = site_info["site_id"]
            site_name = site_info["site_name"]

            try:
                resp = mistapi.api.v1.sites.devices.listSiteDevices(apisession, site_id, type="gateway", limit=1000)
                devices = resp.data if hasattr(resp, "data") else []

                for device in devices:
                    if isinstance(device, dict):
                        all_gateways.append({"device": device, "site_id": site_id, "site_name": site_name})
            except Exception as error:
                logging.warning(f"Error scanning site {site_name}: {error}")
                continue

        # Check if any gateways exist
        if not all_gateways:
            print(f"\n  No gateway devices found in the {len(self.template_sites)} sites using this template.")
            print("  Gateways must be assigned to sites before checking for port overrides.")
            logging.info("Menu #167: No gateway devices found in template sites")
            return []

        print(f"\n  Found {len(all_gateways)} gateway devices. Checking for WAN port overrides...")

        # Second pass: Check each gateway for WAN port overrides
        devices_with_overrides = []
        for gateway_info in all_gateways:
            device = gateway_info["device"]
            site_id = gateway_info["site_id"]
            site_name = gateway_info["site_name"]

            device_id = device.get("id", "")
            device_name = device.get("name", "Unknown Device")
            port_config = device.get("port_config", {})

            if not isinstance(port_config, dict) or not port_config:
                continue

            # Find WAN ports with device-level overrides
            overridden_wan_ports = []
            for port_name, port_settings in port_config.items():
                if not isinstance(port_settings, dict):
                    continue

                # Check if this is a WAN port (usage == "wan")
                if port_settings.get("usage") != "wan":
                    continue

                # This WAN port has a device-level override - collect its current probe config
                current_probe = port_settings.get("wan_probe_override", {})
                current_ips = current_probe.get("ips", []) if isinstance(current_probe, dict) else []
                current_profile = current_probe.get("probe_profile", "") if isinstance(current_probe, dict) else ""

                overridden_wan_ports.append(
                    {
                        "port_name": port_name,
                        "current_ips": current_ips,
                        "current_profile": current_profile,
                        "port_settings": port_settings,
                    }
                )

            if overridden_wan_ports:
                devices_with_overrides.append(
                    {
                        "device_id": device_id,
                        "device_name": device_name,
                        "site_id": site_id,
                        "site_name": site_name,
                        "overridden_wan_ports": overridden_wan_ports,
                    }
                )

        if not devices_with_overrides:
            print(f"\n  No WAN port overrides found on the {len(all_gateways)} gateway devices.")
            print("  All devices are using template-level WAN configuration.")
            logging.info("Menu #167: No devices with WAN port overrides found")
            return []

        total_ports = sum(len(d["overridden_wan_ports"]) for d in devices_with_overrides)
        print(f"\n  Found {len(devices_with_overrides)} devices with {total_ports} overridden WAN ports")
        logging.info(f"Found {len(devices_with_overrides)} devices with {total_ports} overridden WAN ports")
        return devices_with_overrides

    def _show_preview(self, devices_with_overrides: list[dict[str, Any]], dry_run: bool) -> None:  # nosec B101
        """Display preview of changes to be made."""
        assert self.selected_template is not None, "Template must be selected"  # nosec B101
        total_ports = sum(len(d["overridden_wan_ports"]) for d in devices_with_overrides)

        print("\n  Preview of Changes:")
        print(f"  Template: {self.selected_template['name']}")
        print(f"  Devices: {len(devices_with_overrides)}")
        print(f"  Overridden WAN Ports: {total_ports}")

        # Show first 5 devices as preview
        preview_count = min(5, len(devices_with_overrides))
        print(f"\n  Sample devices (showing {preview_count} of {len(devices_with_overrides)}):")

        for device in devices_with_overrides[:preview_count]:
            print(f"\n   Device: {device['device_name']} ({device['site_name']})")
            for wan_port in device["overridden_wan_ports"]:
                port = wan_port["port_name"]
                current_ips = wan_port["current_ips"] or ["(none)"]
                current_profile = wan_port["current_profile"] or "(none)"
                print(f"     {port}:")
                print(f"       Current: ips={current_ips}, profile={current_profile}")
                print(f"       New:     ips={self.probe_ips}, profile={self.probe_profile}")

        if len(devices_with_overrides) > preview_count:
            print(f"\n   ... and {len(devices_with_overrides) - preview_count} more devices")

    def _confirm_operation(self, device_count: int) -> bool:
        """Prompt for confirmation. Returns True if confirmed."""
        print(f"\n  {'=' * 70}")
        print(f"  !? CRITICAL: This will modify {device_count} gateway devices")
        print("  !? Type 'APPLY' (all caps) to proceed or anything else to cancel")
        print(f"  {'=' * 70}")

        confirmation = InputUtils.safe_input(
            "\n  Confirmation: ",
            context="wan_probe_device_apply_confirmation",
        ).strip()
        if confirmation != "APPLY":
            print(" Operation cancelled.")
            logging.info("Menu #167 cancelled by user at final confirmation")
            return False
        return True

    def _apply_changes(self, devices_with_overrides: list[dict[str, Any]], dry_run: bool) -> list[dict[str, Any]]:
        """Apply probe configuration changes to devices. Returns results."""
        print("\n  Applying WAN probe configuration to device overrides...")
        results = []

        for device in tqdm(devices_with_overrides, desc="Updating devices", unit="device"):  # type: ignore[no-untyped-call]
            if ConfigUtils.check_stop_signal():
                break
            result = self._update_single_device(device, dry_run)
            results.append(result)

        return results

    def _update_single_device(self, device: dict[str, Any], dry_run: bool) -> dict[str, Any]:  # nosec B101
        """Update a single device's overridden WAN port probe configuration."""
        assert self.selected_template is not None, "Template must be selected"  # nosec B101
        device_id = device["device_id"]
        device_name = device["device_name"]
        site_id = device["site_id"]
        site_name = device["site_name"]

        result = {
            "device_name": device_name,
            "device_id": device_id,
            "site_name": site_name,
            "site_id": site_id,
            "template_name": self.selected_template["name"],
            "ports_updated": [],
            "status": "",
            "error": "",
        }

        try:
            # Fetch current device configuration
            logging.debug(f"Fetching device config for {device_name}")
            resp = mistapi.api.v1.sites.devices.getSiteDevice(apisession, site_id, device_id)
            device_config = resp.data if hasattr(resp, "data") else {}

            if not isinstance(device_config, dict):
                result["status"] = "SKIPPED"
                result["error"] = "Invalid device config structure"
                return result

            port_config = device_config.get("port_config", {})
            if not isinstance(port_config, dict):
                result["status"] = "SKIPPED"
                result["error"] = "No port_config found"
                return result

            # Update probe config for each overridden WAN port
            ports_modified = []
            for wan_port in device["overridden_wan_ports"]:
                port_name = wan_port["port_name"]

                if port_name in port_config:
                    # Ensure port_config[port_name] is a dict
                    if not isinstance(port_config[port_name], dict):
                        port_config[port_name] = {}

                    # Set wan_probe_override
                    port_config[port_name]["wan_probe_override"] = {
                        "ips": self.probe_ips.copy(),
                        "probe_profile": self.probe_profile,
                    }
                    ports_modified.append(port_name)
                    logging.debug(f"Device {device_name}: Updated {port_name} probe config")

            if ports_modified:
                device_config["port_config"] = port_config
                result["ports_updated"] = ports_modified

                if dry_run:
                    result["status"] = "DRY-RUN"
                    logging.info(f"DRY-RUN: Would update device {device_name} ports: {ports_modified}")
                else:
                    logging.debug(f"Updating device {device_name} via API")
                    update_resp = mistapi.api.v1.sites.devices.updateSiteDevice(
                        apisession, site_id, device_id, body=device_config
                    )

                    if update_resp.status_code == 200:
                        result["status"] = "SUCCESS"
                        logging.info(f"Successfully updated device {device_name}")
                    else:
                        result["status"] = "FAILED"
                        result["error"] = f"API returned status {update_resp.status_code}"
                        logging.error(f"Failed to update device {device_name}: {update_resp.status_code}")
            else:
                result["status"] = "SKIPPED"
                result["error"] = "No matching ports found in current config"

        except Exception as error:
            result["status"] = "ERROR"
            result["error"] = str(error)
            logging.error(f"Error updating device {device_name}: {error}")
            logging.error(traceback.format_exc())

        return result

    def _generate_report(self, results: list[dict[str, Any]], dry_run: bool) -> None:  # nosec B101
        """Generate and display final report."""
        assert self.selected_template is not None, "Template must be selected"  # nosec B101
        template_name = self.selected_template["name"]  # Extract once after assertion

        # Prepare report data
        report_data = []
        for result in results:
            report_data.append(
                {
                    "device_name": result["device_name"],
                    "device_id": result["device_id"],
                    "site_name": result["site_name"],
                    "site_id": result["site_id"],
                    "template_name": result["template_name"],
                    "ports_updated": ", ".join(result["ports_updated"]) if result["ports_updated"] else "",
                    "port_count": len(result["ports_updated"]),
                    "status": result["status"],
                    "error": result["error"],
                    "new_probe_ips": ", ".join(self.probe_ips),
                    "new_probe_profile": self.probe_profile,
                }
            )

        output_file = "GatewayDevice_WAN_Probe_Override_Audit.csv"
        DataExporter.save_data_to_output(report_data, output_file)  # type: ignore[no-untyped-call]

        # Calculate summary
        total_ports = sum(len(r["ports_updated"]) for r in results)

        if dry_run:
            dry_run_count = sum(1 for r in results if r["status"] == "DRY-RUN")
            print("\n  WAN Probe Device Override DRY-RUN Complete!")
            print("=" * 70)
            print("  >> DRY-RUN MODE: No actual changes were made")
            print(f"  Template: {template_name}")
            print(f"  Devices Analyzed: {len(results)}")
            print(f"  Would Update: {dry_run_count} devices")
            print(f"  WAN Ports: {total_ports}")
            print("\n  >> To apply changes, run without --dry-run flag")
        else:
            success_count = sum(1 for r in results if r["status"] == "SUCCESS")
            failure_count = len(results) - success_count

            print("\n  WAN Probe Device Override Complete!")
            print("=" * 70)
            print(f"  Template: {template_name}")
            print(f"  Devices Updated: {success_count}")
            print(f"  Devices Failed: {failure_count}")
            print(f"  WAN Ports Configured: {total_ports}")

            if success_count > 0:
                print("\n  Configuration Applied:")
                print(f"    Probe IPs: {self.probe_ips}")
                print(f"    Probe Profile: {self.probe_profile}")

            if failure_count > 0:
                print(f"\n  !? {failure_count} devices failed - check audit report")

        print(f"\n  Report saved to: {output_file}")
        print("=" * 70)

        logging.warning(
            f"Menu #167 DESTRUCTIVE operation complete: {sum(1 for r in results if r['status'] == 'SUCCESS')} devices updated"  # noqa: E501
        )


